struct ActivityDetection: Identifiable, Equatable {
    enum Kind: String {
        case activityCandidate = "Activity candidate"
        case workout = "Workout"
        case sleepCandidate = "Sleep candidate"
        case restCandidate = "Rest candidate"
    }

    enum Confidence: String {
        case low
        case medium
        case high
    }

    let id: UUID
    let kind: Kind
    let confidence: Confidence
    let start: Date
    let end: Date
    let duration: TimeInterval
    let avgHR: Int
    let peakHR: Int
    let reason: String
    /// Optional, classifier-owned context. HR-only detection always leaves this
    /// nil because exertion cannot identify an activity type. A caller may set
    /// it only from independently validated, time-aligned classification.
    let suggestedActivityType: AtriaWorkoutActivityType?

    init(id: UUID,
         kind: Kind,
         confidence: Confidence,
         start: Date,
         end: Date,
         duration: TimeInterval,
         avgHR: Int,
         peakHR: Int,
         reason: String,
         suggestedActivityType: AtriaWorkoutActivityType? = nil) {
        self.id = id
        self.kind = kind
        self.confidence = confidence
        self.start = start
        self.end = end
        self.duration = duration
        self.avgHR = avgHR
        self.peakHR = peakHR
        self.reason = reason
        self.suggestedActivityType = suggestedActivityType
    }
}

struct WorkoutReadiness {
    private static let reviewMinimumObservedDuration: TimeInterval = 15 * 60
    private static let reviewMinimumCoveragePercent = 40
    /// A deliberately narrower fallback for a long saved session whose radio
    /// gap leaves just under the normal 15-minute review floor. This never
    /// participates in `ready`; it can only offer an explicitly low-confidence
    /// review card when the observed HR distribution is unambiguously strong.
    private static let gappedReviewMinimumObservedDuration: TimeInterval = 12 * 60
    private static let gappedReviewMinimumAverageOverRest = 35
    private static let gappedReviewMinimumP95OverRest = 40
    private static let gappedReviewMinimumPeakOverRest = 55
    private static let gappedReviewMinimumPeakAboveAverage = 20
    private static let reviewMinimumPeakOverRest = 45
    private static let reviewMinimumP95OverRest = 35
    private static let reviewMinimumModerateStrengthPeakOverRest = 35
    private static let reviewMinimumModerateStrengthP95OverRest = 30
    private static let reviewMinimumElevatedSeconds: TimeInterval = 4 * 60
    private static let reviewMinimumElevatedBout: TimeInterval = 90
    private static let reviewMinimumBorderlineSeconds: TimeInterval = 5 * 60
    private static let reviewMinimumBorderlineBout: TimeInterval = 90

    let duration: TimeInterval
    let observedDuration: TimeInterval
    let avgHR: Int
    let peakHR: Int
    let p90HR: Int
    let p95HR: Int
    let p99HR: Int
    let thresholdHR: Int
    let thresholdGapBPM: Int
    let samplesAboveThreshold: Int
    let samplesAboveBorderline: Int
    let elevatedSeconds: TimeInterval
    let elevatedFraction: Double
    let longestElevatedBout: TimeInterval
    let borderlineThresholdHR: Int
    let borderlineElevatedSeconds: TimeInterval
    let borderlineLongestBout: TimeInterval
    let borderlineElevatedFraction: Double
    let requiredElevatedSeconds: TimeInterval
    let requiredElevatedBout: TimeInterval
    let droppedGapSeconds: TimeInterval
    let maxSampleGap: TimeInterval
    let gapCount: Int
    let streamCoveragePercent: Int
    let primaryBlocker: String
    let avgOverRest: Int
    let peakOverRest: Int
    /// Contact-quality-gated companions to `elevatedSeconds`/`longestElevatedBout`:
    /// zero unless the session backs its elevation with RR presence or an
    /// unbroken accepted-HR stream (see `SavedSession.hrRRSampleCount`/
    /// `hrAcceptedGapsValue`/`hrMaxAcceptedGapValue`). A loose-contact/reconnect
    /// artifact run can still show up in `elevatedSeconds` but cannot satisfy
    /// this pair, so it cannot alone make a session `ready` or review-worthy.
    let contactQualifiedElevatedSeconds: TimeInterval
    let contactQualifiedLongestBout: TimeInterval
    /// True when this session's own audit counters show the watchdog-cycling /
    /// loose-contact fingerprint (heavy artifact hold+drop share, heavy zero
    /// share, or repeated large accepted-stream gaps). Such a session must
    /// never source an auto-detected workout, regardless of its raw HR values.
    let contactCompromised: Bool
    /// True when RR/IBI intervals are present but their implied heart rate
    /// disagrees with the session's own reported average HR by more than the
    /// sanity-ceiling tolerance -- the strap's own RR channel contradicting its
    /// reported HR is treated as a hard contact-artifact rejection.
    let rrDisagreement: Bool
    let ready: Bool

    var status: String {
        ready ? "ready" : "learning"
    }

    var streamBlocked: Bool {
        primaryBlocker.contains("stream_gaps") || streamCoveragePercent < 75
    }

    var nearMiss: Bool {
        guard !ready else { return false }
        let enoughObservedData = observedDuration >= 15 * 60
        let enoughSparseCoverageToInspect = streamCoveragePercent >= Self.reviewMinimumCoveragePercent
        let closeToThreshold = thresholdGapBPM <= 5 || elevatedSeconds > 0
        return enoughObservedData && enoughSparseCoverageToInspect && closeToThreshold
    }

    var nearMissReason: String {
        guard nearMiss else { return "none" }
        var reasons: [String] = []
        if streamBlocked {
            reasons.append("stream_coverage_low")
        }
        if thresholdGapBPM > 0 {
            reasons.append("peak_within_\(thresholdGapBPM)_bpm_below_threshold")
        }
        if elevatedSeconds < requiredElevatedSeconds {
            reasons.append("elevated_seconds_below_required")
        }
        if longestElevatedBout < requiredElevatedBout {
            reasons.append("continuous_bout_below_required")
        }
        return reasons.isEmpty ? "near_miss_low_confidence" : reasons.joined(separator: "+")
    }

    var strengthCandidate: Bool {
        guard !ready else { return false }
        // Contact-artifact hardening: a compromised stream or an RR channel
        // that contradicts its own reported HR must never source a strength
        // candidate, even diagnostically -- see reviewWorthyCandidate below,
        // which previously was the only strength-path gate enforcing this.
        guard !contactCompromised, !rrDisagreement else { return false }
        guard observedDuration >= Self.reviewMinimumObservedDuration,
              streamCoveragePercent >= Self.reviewMinimumCoveragePercent else { return false }
        let closeToWorkoutBand = thresholdGapBPM <= 5 || elevatedSeconds > 0
        let hasStrengthEffort = peakOverRest >= Self.reviewMinimumPeakOverRest
            || p95HR - max(0, peakHR - peakOverRest) >= Self.reviewMinimumP95OverRest
        // A single near-threshold optical spike is common during eating, phone
        // use, and ordinary wrist motion. Strength review needs a sustained
        // moderate band, not merely a peak close to the workout threshold.
        let hasBorderlineEvidence = borderlineElevatedSeconds >= Self.reviewMinimumBorderlineSeconds
            && borderlineLongestBout >= Self.reviewMinimumBorderlineBout
        return closeToWorkoutBand && hasStrengthEffort && hasBorderlineEvidence
    }

    var moderateStrengthReviewCandidate: Bool {
        guard !ready else { return false }
        guard !contactCompromised, !rrDisagreement else { return false }
        guard observedDuration >= Self.reviewMinimumObservedDuration,
              streamCoveragePercent >= Self.reviewMinimumCoveragePercent else { return false }
        let p95OverRest = p95HR - max(0, peakHR - peakOverRest)
        return peakOverRest >= Self.reviewMinimumModerateStrengthPeakOverRest
            && p95OverRest >= Self.reviewMinimumModerateStrengthP95OverRest
    }

    var gappedStrengthReviewCandidate: Bool {
        guard !ready, !strengthCandidate, !moderateStrengthReviewCandidate else { return false }
        guard streamBlocked, !contactCompromised, !rrDisagreement else { return false }
        guard observedDuration >= Self.gappedReviewMinimumObservedDuration,
              observedDuration < Self.reviewMinimumObservedDuration,
              streamCoveragePercent >= Self.reviewMinimumCoveragePercent else { return false }
        // Unlike the ordinary strength heuristic, the shortened observed-time
        // fallback requires both a strong whole-window distribution and
        // contact-qualified sustained effort. A lone spike, stress plateau, or
        // reconnect artifact therefore cannot create a prompt.
        let strongDistribution = avgOverRest >= Self.gappedReviewMinimumAverageOverRest
            && p95HR - max(0, peakHR - peakOverRest) >= Self.gappedReviewMinimumP95OverRest
            && peakOverRest >= Self.gappedReviewMinimumPeakOverRest
            && peakHR - avgHR >= Self.gappedReviewMinimumPeakAboveAverage
        let sustained = contactQualifiedElevatedSeconds >= Self.reviewMinimumElevatedSeconds
            && contactQualifiedLongestBout >= Self.reviewMinimumElevatedBout
            && borderlineElevatedSeconds >= Self.reviewMinimumBorderlineSeconds
            && borderlineLongestBout >= Self.reviewMinimumBorderlineBout
        return strongDistribution && sustained
    }

    var strengthCandidateReason: String {
        guard strengthCandidate || moderateStrengthReviewCandidate || gappedStrengthReviewCandidate else { return "none" }
        var reasons = ["diagnostic_only"]
        if streamBlocked {
            reasons.append("stream_gaps_prevent_count")
        }
        if thresholdGapBPM > 0 {
            reasons.append("peak_within_\(thresholdGapBPM)_bpm_below_hrr50")
        }
        if borderlineElevatedSeconds > 0 {
            reasons.append("borderline_hr_band_\(Int(borderlineElevatedSeconds.rounded()))s")
        }
        if elevatedSeconds < requiredElevatedSeconds {
            reasons.append("workout_band_time_insufficient")
        }
        if longestElevatedBout < requiredElevatedBout {
            reasons.append("continuous_bout_insufficient")
        }
        if moderateStrengthReviewCandidate && !strengthCandidate {
            reasons.append("moderate_strength_review")
        }
        if gappedStrengthReviewCandidate {
            reasons.append("strong_gapped_effort_review")
        }
        return reasons.joined(separator: "+")
    }

    var reviewWorthyCandidate: Bool {
        guard !ready else { return true }
        // Contact-artifact hardening: a compromised stream or an RR channel that
        // contradicts its own reported HR may still surface as a diagnostic
        // near-miss/strength candidate above, but it must never be promoted to
        // a review-worthy (auto-detect prompt) candidate.
        guard !contactCompromised, !rrDisagreement else { return false }
        if gappedStrengthReviewCandidate { return true }
        guard observedDuration >= Self.reviewMinimumObservedDuration,
              streamCoveragePercent >= Self.reviewMinimumCoveragePercent else { return false }
        if nearMiss {
            // Contact-quality-gated: an elevated-looking near-miss can only be
            // promoted on evidence that is itself RR/continuity-backed, so a
            // loose-contact blip cannot alone clear this bar (borderline-based
            // strengthCandidate promotion below is unaffected).
            return (contactQualifiedElevatedSeconds >= Self.reviewMinimumElevatedSeconds
                    && contactQualifiedLongestBout >= Self.reviewMinimumElevatedBout)
                || strengthCandidate
        }
        if strengthCandidate {
            return borderlineElevatedSeconds >= Self.reviewMinimumBorderlineSeconds
                && borderlineLongestBout >= Self.reviewMinimumBorderlineBout
        }
        if moderateStrengthReviewCandidate {
            return contactQualifiedElevatedSeconds >= Self.reviewMinimumElevatedSeconds
                && contactQualifiedLongestBout >= Self.reviewMinimumElevatedBout
        }
        return false
    }

    var hrDistributionBelowWorkoutBand: Bool {
        guard !ready, thresholdHR > 0 else { return false }
        return p95HR < thresholdHR && elevatedSeconds < 60
    }

    var nextAction: String {
        if ready { return "count_workout" }
        if strengthCandidate || moderateStrengthReviewCandidate || gappedStrengthReviewCandidate {
            return "observe_strength_signal_without_counting_and_validate_hr_reference"
        }
        let hasStreamGap = streamBlocked
        let needsHRReference = peakHR < thresholdHR
        if hasStreamGap && needsHRReference {
            return "fix_stream_continuity_and_validate_intensity"
        }
        if hasStreamGap {
            return "fix_stream_continuity_before_counting"
        }
        if needsHRReference {
            return "validate_intensity_with_reference_or_profile"
        }
        if hrDistributionBelowWorkoutBand {
            return "validate_wrist_hr_underreporting_or_profile_before_more_workouts"
        }
        if elevatedSeconds < requiredElevatedSeconds || longestElevatedBout < requiredElevatedBout {
            return "keep_learning_until_sustained_hr"
        }
        return "inspect_detector_inputs"
    }

    var reason: String {
        if observedDuration < 10 * 60 {
            if gapCount > 0 {
                return "observed_duration_below_10m_stream_gaps"
            }
            return "duration_below_10m"
        }
        if elevatedSeconds < requiredElevatedSeconds {
            return "elevated_seconds_below_required"
        }
        if longestElevatedBout < requiredElevatedBout {
            return "elevated_bout_below_required"
        }
        return ready ? "sustained_elevated_hr" : "detector_not_workout"
    }
}

struct DailyRollup {
    let day: Date
    let sessions: Int
    let activityCandidates: Int
    let workouts: Int
    let confirmedWorkouts: Int
    let restCandidates: Int
    let sleepReady: Int
    let sleepCandidates: Int
    let duration: TimeInterval
    let sleepDuration: TimeInterval?
    let sleepSpan: TimeInterval?
    let sleepStart: Date?
    let sleepEnd: Date?
    let sleepSource: String?
    let sleepStageSegments: [SleepStageSegment]
    let strain: Double
    let avgHRV: Int?
    /// Exact count of qualified five-minute HRV windows contributing to this
    /// rollup. Zero is both the safe legacy default and the representation for
    /// unknown evidence; a bare aggregate HRV value never implies three.
    var hrvWindowCount: Int = 0
    let restingHR: Int?
    let avgRespiratoryRate: Double?
}

struct SavedDailyMetric: Codable, Identifiable, Equatable {
    static let codingCalendarUserInfoKey = CodingUserInfoKey(rawValue: "SavedDailyMetric.calendar")!

    let day: Date
    let recoveryPercent: Int?
    let recoveryConfidence: String
    let hrv: Int?
    let restingHR: Int?
    let respiratoryRate: Double?
    let sleepDuration: TimeInterval?
    let sleepSpan: TimeInterval?
    let sleepStart: Date?
    let sleepEnd: Date?
    let sleepSource: String?
    let sleepStageSegments: [SleepStageSegment]
    let sleepConsistencyPercent: Int?
    let strain: Double?
    let skinTemperatureDeviationCelsius: Double?
    let recoverySummary: FrozenRecoverySummary?

    var id: Date { day }

    init(day: Date,
         recoveryPercent: Int?,
         recoveryConfidence: String,
         hrv: Int?,
         restingHR: Int?,
         respiratoryRate: Double?,
         sleepDuration: TimeInterval?,
         sleepSpan: TimeInterval?,
         sleepStart: Date?,
         sleepEnd: Date?,
         sleepSource: String?,
         sleepStageSegments: [SleepStageSegment],
         sleepConsistencyPercent: Int?,
         strain: Double?,
         skinTemperatureDeviationCelsius: Double? = nil,
         recoverySummary: FrozenRecoverySummary? = nil) {
        let coherentSummary = recoverySummary.flatMap { summary in
            recoveryPercent == nil || summary.score == recoveryPercent
                ? summary.replacingScoredDay(day)
                : nil
        }
        self.day = day
        self.recoveryPercent = coherentSummary?.score ?? recoveryPercent
        self.recoveryConfidence = coherentSummary?.confidence ?? recoveryConfidence
        self.hrv = hrv
        self.restingHR = restingHR
        self.respiratoryRate = respiratoryRate
        self.sleepDuration = sleepDuration
        self.sleepSpan = sleepSpan
        self.sleepStart = sleepStart
        self.sleepEnd = sleepEnd
        self.sleepSource = sleepSource
        self.sleepStageSegments = sleepStageSegments
        self.sleepConsistencyPercent = sleepConsistencyPercent
        self.strain = strain
        self.skinTemperatureDeviationCelsius = skinTemperatureDeviationCelsius
        self.recoverySummary = coherentSummary
    }

    private enum CodingKeys: String, CodingKey {
        case day
        case civilDay
        case civilTimeZoneOffsetSeconds
        case recoveryPercent
        case recoveryConfidence
        case hrv
        case restingHR
        case respiratoryRate
        case sleepDuration
        case sleepSpan
        case sleepStart
        case sleepEnd
        case sleepSource
        case sleepStageSegments
        case sleepConsistencyPercent
        case strain
        case skinTemperatureDeviationCelsius
        case recoverySummary
    }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        let calendar = (decoder.userInfo[Self.codingCalendarUserInfoKey] as? Calendar) ?? .current
        let legacyDay = try container.decode(Date.self, forKey: .day)
        if let civilDay = try container.decodeIfPresent(String.self, forKey: .civilDay),
           let materializedDay = Self.materializedDay(from: civilDay, calendar: calendar) {
            day = materializedDay
        } else {
            day = legacyDay
        }
        let decodedRecoveryPercent = try container.decodeIfPresent(Int.self, forKey: .recoveryPercent)
        let decodedRecoveryConfidence = try container.decode(String.self, forKey: .recoveryConfidence)
        hrv = try container.decodeIfPresent(Int.self, forKey: .hrv)
        restingHR = try container.decodeIfPresent(Int.self, forKey: .restingHR)
        respiratoryRate = try container.decodeIfPresent(Double.self, forKey: .respiratoryRate)
        sleepDuration = try container.decodeIfPresent(TimeInterval.self, forKey: .sleepDuration)
        sleepSpan = try container.decodeIfPresent(TimeInterval.self, forKey: .sleepSpan)
        sleepStart = try container.decodeIfPresent(Date.self, forKey: .sleepStart)
        sleepEnd = try container.decodeIfPresent(Date.self, forKey: .sleepEnd)
        sleepSource = try container.decodeIfPresent(String.self, forKey: .sleepSource)
        sleepStageSegments = try container.decode([SleepStageSegment].self, forKey: .sleepStageSegments)
        sleepConsistencyPercent = try container.decodeIfPresent(Int.self, forKey: .sleepConsistencyPercent)
        strain = try container.decodeIfPresent(Double.self, forKey: .strain)
        skinTemperatureDeviationCelsius = try container.decodeIfPresent(
            Double.self,
            forKey: .skinTemperatureDeviationCelsius
        )
        let decodedSummary = try container.decodeIfPresent(FrozenRecoverySummary.self,
                                                           forKey: .recoverySummary)
        let materializedDay = day
        let coherentSummary = decodedSummary.flatMap { summary in
            decodedRecoveryPercent == nil || summary.score == decodedRecoveryPercent
                ? summary.replacingScoredDay(materializedDay)
                : nil
        }
        recoverySummary = coherentSummary
        recoveryPercent = coherentSummary?.score ?? decodedRecoveryPercent
        recoveryConfidence = coherentSummary?.confidence ?? decodedRecoveryConfidence
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        let calendar = (encoder.userInfo[Self.codingCalendarUserInfoKey] as? Calendar) ?? .current
        try container.encode(day, forKey: .day)
        try container.encode(Self.civilDay(for: day, calendar: calendar), forKey: .civilDay)
        try container.encode(calendar.timeZone.secondsFromGMT(for: day),
                             forKey: .civilTimeZoneOffsetSeconds)
        try container.encodeIfPresent(recoveryPercent, forKey: .recoveryPercent)
        try container.encode(recoveryConfidence, forKey: .recoveryConfidence)
        try container.encodeIfPresent(hrv, forKey: .hrv)
        try container.encodeIfPresent(restingHR, forKey: .restingHR)
        try container.encodeIfPresent(respiratoryRate, forKey: .respiratoryRate)
        try container.encodeIfPresent(sleepDuration, forKey: .sleepDuration)
        try container.encodeIfPresent(sleepSpan, forKey: .sleepSpan)
        try container.encodeIfPresent(sleepStart, forKey: .sleepStart)
        try container.encodeIfPresent(sleepEnd, forKey: .sleepEnd)
        try container.encodeIfPresent(sleepSource, forKey: .sleepSource)
        try container.encode(sleepStageSegments, forKey: .sleepStageSegments)
        try container.encodeIfPresent(sleepConsistencyPercent, forKey: .sleepConsistencyPercent)
        try container.encodeIfPresent(strain, forKey: .strain)
        try container.encodeIfPresent(skinTemperatureDeviationCelsius,
                                      forKey: .skinTemperatureDeviationCelsius)
        try container.encodeIfPresent(recoverySummary, forKey: .recoverySummary)
    }

    static func civilDay(for date: Date, calendar: Calendar) -> String {
        let components = calendar.dateComponents([.year, .month, .day], from: date)
        return String(format: "%04d-%02d-%02d",
                      components.year ?? 0,
                      components.month ?? 0,
                      components.day ?? 0)
    }

    static func materializedDay(from civilDay: String, calendar: Calendar) -> Date? {
        let parts = civilDay.split(separator: "-", omittingEmptySubsequences: false)
        guard parts.count == 3,
              parts[0].count == 4,
              parts[1].count == 2,
              parts[2].count == 2,
              let year = Int(parts[0]),
              let month = Int(parts[1]),
              let day = Int(parts[2]),
              let date = calendar.date(from: DateComponents(year: year, month: month, day: day)) else {
            return nil
        }
        let materialized = calendar.dateComponents([.year, .month, .day], from: date)
        guard materialized.year == year,
              materialized.month == month,
              materialized.day == day else {
            return nil
        }
        return calendar.startOfDay(for: date)
    }
}

struct DailyMetricSparklineCache: Equatable {
    let recovery: [Int]?
    let hrv: [Int]?
    let restingHeartRate: [Int]?
    let sleep: [Int]?
    let strain: [Int]?

    static let empty = DailyMetricSparklineCache(recovery: nil,
                                                 hrv: nil,
                                                 restingHeartRate: nil,
                                                 sleep: nil,
                                                 strain: nil)
}

struct AtriaActivityCalibrationEvidence: Codable, Equatable {
    static let schemaVersion = 1
    static let algorithmVersion = "activity_calibration_5m_v1"
    static let binSeconds: TimeInterval = 5 * 60
    static let maximumBins = 288
    static let maximumSourceSessions = 32
    static let allowedStatuses: Set<String> = [
        "no_sensor_evidence",
        "insufficient_hr",
        "insufficient_validated_motion",
        "window_exceeds_bounded_snapshot",
        "ready",
    ]
    static let allowedMotionProvenance: Set<String> = [
        "none",
        AtriaRecoveredMotionEpoch.source,
    ]

    struct Bin: Codable, Equatable {
        let startOffsetSeconds: Int
        let durationSeconds: Int
        let hrSampleCount: Int
        let averageHR: Int?
        let minimumHR: Int?
        let maximumHR: Int?
        let validatedMotionEpochs: Int
        let validatedMotionCoverageFraction: Double
        let meanStillnessRatio: Double?
        let meanMovementIntensity: Double?
        let meanP95VectorDelta: Double?
    }

    struct MotionSummary: Codable, Equatable {
        let epochCount: Int
        let validatedEpochCount: Int
        let validatedCoverageFraction: Double
        let meanStillnessRatio: Double?
        let meanMovementIntensity: Double?
        let meanP95VectorDelta: Double?
        let provenance: String
    }

    let schemaVersion: Int
    let algorithmVersion: String
    let windowStart: Date
    let windowEnd: Date
    let sourceSessionIDs: [UUID]
    let sourceSessionCount: Int
    let sourceSessionIDsTruncated: Bool
    let status: String
    let bins: [Bin]
    let motion: MotionSummary
}

struct UserConfirmedWorkout: Codable, Identifiable, Equatable {
    let id: String
    let createdAt: Date
    let start: Date
    let end: Date
    let label: String
    let source: String
    let confidence: String
    let sessions: Int
    let samples: Int
    let avgHR: Int
    let peakHR: Int
    let p95HR: Int
    let p99HR: Int
    let thresholdHR: Int
    let streamCoveragePercent: Int
    let observedDuration: TimeInterval
    let reason: String
    var activityType: String? = nil
    var activitySubtype: String? = nil
    var exerciseNames: [String]? = nil
    var strengthSets: [LoggedSet]? = nil
    var excludedIntervals: [ExcludedInterval]? = nil
    var reviewSource: String? = nil
    /// Stable identity of the detector suggestion the user explicitly labelled.
    /// Nil for manual/live workouts and legacy records.
    var reviewCandidateID: String? = nil
    /// Compact, bounded sensor snapshot created only when the user explicitly
    /// labels a detector suggestion. It deliberately contains no user label;
    /// `label`/`activityType` remain the mutable canonical truth.
    var activityCalibrationEvidence: AtriaActivityCalibrationEvidence? = nil
    var strain: Double? = nil
    /// Version of `AtriaAnalytics.Strain`'s 0–21 display curve used for this
    /// persisted detail value. Nil is a legacy record and is only migrated when
    /// its original window still has sufficient strap HR evidence.
    var strainCalibrationVersion: Int? = nil
    var activeEnergyKilocalories: Double? = nil
    var activeEnergyConfidence: String? = nil
    var zoneSeconds: [String: TimeInterval]? = nil
    var eventTimeZoneIdentifier: String? = nil
    /// Pause-adjusted strap-motion steps captured for this exact explicit
    /// workout window. Optional fields keep every pre-step-schema workout
    /// decodable and prevent manually added/detected activities from implying
    /// motion evidence they never recorded.
    var workoutSteps: Int? = nil
    var workoutStepsAreEstimated: Bool? = nil
    var workoutStepsCapturedAt: Date? = nil

    var duration: TimeInterval { end.timeIntervalSince(start) }
}

enum SleepStageKind: String, Codable, CaseIterable, Identifiable {
    case awake
    case light
    case rem
    case sws
    case deep

    var id: String { rawValue }

    var label: String {
        switch self {
        case .awake: return "Awake"
        case .light: return "Light"
        case .rem: return "REM"
        case .sws: return "SWS"
        case .deep: return "Deep"
        }
    }

    /// User-facing stage order: SWS is folded into Deep at the presentation layer
    /// (SWS is N3/deep sleep; the algorithm's separate `.sws`/`.deep` HR-delta bands
    /// are an artifact of stage() thresholds, not two physiologically distinct stages).
    static let displayOrder: [SleepStageKind] = [.awake, .light, .rem, .deep]

    /// Maps `.sws` -> `.deep` for display; all other cases pass through unchanged.
    /// The stored/algorithm taxonomy (stage(), persisted segments) is untouched.
    var displayStage: SleepStageKind {
        self == .sws ? .deep : self
    }
}

enum SleepStageEvidence: String, Codable, Equatable {
    case none
    case manualEstimate
    case sensorResearch
    case validated

    var label: String {
        switch self {
        case .none: return "Stages not ready"
        case .manualEstimate: return "Manual estimate"
        case .sensorResearch: return "Estimated stages"
        case .validated: return "Checked stages"
        }
    }
}

struct SleepStageSegment: Codable, Identifiable, Equatable {
    let id: String
    let start: Date
    let end: Date
    let stage: SleepStageKind

    var duration: TimeInterval {
        max(0, end.timeIntervalSince(start))
    }
}

struct UserConfirmedSleep: Codable, Identifiable, Equatable {
    let id: String
    let createdAt: Date
    let start: Date
    let end: Date
    let source: String
    let confidence: String
    let sessions: Int
    let samples: Int
    let avgHR: Int
    let peakHR: Int
    let restingHR: Int
    let hrv: Int?
    let hrvWindowCount: Int?
    /// Median RSA-derived breaths/minute from continuous, qualified RR runs
    /// wholly inside this confirmed sleep window. Optional for legacy records
    /// and nights without enough continuous RR evidence.
    let respiratoryRate: Double?
    let duration: TimeInterval
    let span: TimeInterval
    let reason: String
    let motionSource: String
    let motionValidated: Bool
    let stageSegments: [SleepStageSegment]?
    var eventTimeZoneIdentifier: String? = nil

    /// A resumed-sleep review starts from a broad low-HR capture window.
    /// Observed `duration` is sensor coverage, not necessarily time asleep.
    /// When an integrity-valid stage timeline exists, only classified
    /// non-awake epochs receive physiological sleep credit.
    var effectiveSleepDuration: TimeInterval {
        Self.effectiveSleepDuration(source: source,
                                    observedDuration: duration,
                                    start: start,
                                    end: end,
                                    span: span,
                                    stageSegments: stageSegments)
    }

    static func effectiveSleepDuration(source: String,
                                       observedDuration: TimeInterval,
                                       start: Date,
                                       end: Date,
                                       span: TimeInterval,
                                       stageSegments: [SleepStageSegment]?) -> TimeInterval {
        guard source == "resumed_sleep",
              let stageSegments,
              !stageSegments.isEmpty,
              AtriaSleepStageIntegrity.validates(stageSegments,
                                                 start: start,
                                                 end: end,
                                                 duration: observedDuration,
                                                 span: span) else {
            return max(0, observedDuration)
        }
        let classifiedSleep = stageSegments.reduce(0) {
            $0 + ($1.stage == .awake ? 0 : max(0, $1.duration))
        }
        return min(max(0, observedDuration), classifiedSleep)
    }

    init(id: String,
         createdAt: Date,
         start: Date,
         end: Date,
         source: String,
         confidence: String,
         sessions: Int,
         samples: Int,
         avgHR: Int,
         peakHR: Int,
         restingHR: Int,
         hrv: Int?,
         hrvWindowCount: Int?,
         respiratoryRate: Double? = nil,
         duration: TimeInterval,
         span: TimeInterval,
         reason: String,
         motionSource: String,
         motionValidated: Bool,
         stageSegments: [SleepStageSegment]?,
         eventTimeZoneIdentifier: String? = nil) {
        self.id = id
        self.createdAt = createdAt
        self.start = start
        self.end = end
        self.source = source
        self.confidence = confidence
        self.sessions = sessions
        self.samples = samples
        self.avgHR = avgHR
        self.peakHR = peakHR
        self.restingHR = restingHR
        self.hrv = hrv
        self.hrvWindowCount = hrvWindowCount
        self.respiratoryRate = respiratoryRate
        self.duration = duration
        self.span = span
        self.reason = reason
        self.motionSource = motionSource
        self.motionValidated = motionValidated
        self.stageSegments = stageSegments
        self.eventTimeZoneIdentifier = eventTimeZoneIdentifier
    }

    private enum CodingKeys: String, CodingKey {
        case id, createdAt, start, end, source, confidence, sessions, samples
        case avgHR, peakHR, restingHR, hrv, hrvWindowCount, respiratoryRate
        case duration, span, reason, motionSource, motionValidated, stageSegments
        case eventTimeZoneIdentifier
    }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        id = try container.decode(String.self, forKey: .id)
        createdAt = try container.decode(Date.self, forKey: .createdAt)
        start = try container.decode(Date.self, forKey: .start)
        end = try container.decode(Date.self, forKey: .end)
        source = try container.decode(String.self, forKey: .source)
        confidence = try container.decode(String.self, forKey: .confidence)
        sessions = try container.decode(Int.self, forKey: .sessions)
        samples = try container.decode(Int.self, forKey: .samples)
        avgHR = try container.decode(Int.self, forKey: .avgHR)
        peakHR = try container.decode(Int.self, forKey: .peakHR)
        restingHR = try container.decode(Int.self, forKey: .restingHR)
        hrv = try container.decodeIfPresent(Int.self, forKey: .hrv)
        hrvWindowCount = try container.decodeIfPresent(Int.self, forKey: .hrvWindowCount)
        respiratoryRate = try container.decodeIfPresent(Double.self, forKey: .respiratoryRate)
        duration = try container.decode(TimeInterval.self, forKey: .duration)
        span = try container.decode(TimeInterval.self, forKey: .span)
        reason = try container.decode(String.self, forKey: .reason)
        motionSource = try container.decode(String.self, forKey: .motionSource)
        motionValidated = try container.decode(Bool.self, forKey: .motionValidated)
        stageSegments = try container.decodeIfPresent([SleepStageSegment].self, forKey: .stageSegments)
        eventTimeZoneIdentifier = try container.decodeIfPresent(
            String.self,
            forKey: .eventTimeZoneIdentifier
        )
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(id, forKey: .id)
        try container.encode(createdAt, forKey: .createdAt)
        try container.encode(start, forKey: .start)
        try container.encode(end, forKey: .end)
        try container.encode(source, forKey: .source)
        try container.encode(confidence, forKey: .confidence)
        try container.encode(sessions, forKey: .sessions)
        try container.encode(samples, forKey: .samples)
        try container.encode(avgHR, forKey: .avgHR)
        try container.encode(peakHR, forKey: .peakHR)
        try container.encode(restingHR, forKey: .restingHR)
        try container.encodeIfPresent(hrv, forKey: .hrv)
        try container.encodeIfPresent(hrvWindowCount, forKey: .hrvWindowCount)
        try container.encodeIfPresent(respiratoryRate, forKey: .respiratoryRate)
        try container.encode(duration, forKey: .duration)
        try container.encode(span, forKey: .span)
        try container.encode(reason, forKey: .reason)
        try container.encode(motionSource, forKey: .motionSource)
        try container.encode(motionValidated, forKey: .motionValidated)
        try container.encodeIfPresent(stageSegments, forKey: .stageSegments)
        try container.encodeIfPresent(eventTimeZoneIdentifier, forKey: .eventTimeZoneIdentifier)
    }
}

/// A durable dismissal for a sensor-derived sleep/nap window. A single UI-only
/// dismissed ID is insufficient because daily rollups are rebuilt with new IDs;
/// retaining the time window prevents a deleted detection from resurrecting.
struct AtriaDismissedSleepCandidate: Codable, Equatable {
    let start: Date
    let end: Date

    func overlaps(start otherStart: Date, end otherEnd: Date) -> Bool {
        start < otherEnd && end > otherStart
    }

    /// A dismissal applies only when it covers most of the regenerated
    /// candidate. A tiny false-positive fragment must not hide a materially
    /// larger, later-completed night, while a deleted full night stays deleted
    /// across small detector-boundary changes.
    func suppresses(start otherStart: Date, end otherEnd: Date) -> Bool {
        let overlap = min(end, otherEnd).timeIntervalSince(max(start, otherStart))
        guard overlap > 0 else { return false }
        let dismissedDuration = end.timeIntervalSince(start)
        let candidateDuration = otherEnd.timeIntervalSince(otherStart)
        let longest = max(dismissedDuration, candidateDuration)
        return longest > 0 && overlap / longest >= 0.70
    }
}

enum AtriaDismissedSleepCandidateStore {
    private static let key = "atria.sleepReview.dismissedWindows.v1"
    private static let maximumCount = 64

    static func load(defaults: UserDefaults = .standard) -> [AtriaDismissedSleepCandidate] {
        guard let data = defaults.data(forKey: key),
              let decoded = try? JSONDecoder().decode([AtriaDismissedSleepCandidate].self, from: data) else {
            return []
        }
        return decoded.filter { $0.end > $0.start }
    }

    static func save(_ candidates: [AtriaDismissedSleepCandidate],
                     defaults: UserDefaults = .standard) {
        let bounded = Array(candidates
            .filter { $0.end > $0.start }
            .sorted { $0.end > $1.end }
            .prefix(maximumCount))
        guard let data = try? JSONEncoder().encode(bounded) else { return }
        defaults.set(data, forKey: key)
    }
}

/// Durable window identity for a workout the user deleted. Detector candidate
/// IDs can change when sessions are rebuilt, so the time interval—not an
/// ephemeral UI ID—is the authoritative suppression key.
struct AtriaDismissedWorkoutCandidate: Codable, Equatable {
    let start: Date
    let end: Date

    func overlaps(start otherStart: Date, end otherEnd: Date) -> Bool {
        let overlap = min(end, otherEnd).timeIntervalSince(max(start, otherStart))
        guard overlap > 0 else { return false }
        let shortest = min(end.timeIntervalSince(start), otherEnd.timeIntervalSince(otherStart))
        return overlap >= 5 * 60 || (shortest > 0 && overlap / shortest >= 0.70)
    }
}

enum AtriaDismissedWorkoutCandidateStore {
    private static let key = "atria.workoutReview.dismissedWindows.v1"
    private static let maximumCount = 64

    static func load(defaults: UserDefaults = .standard) -> [AtriaDismissedWorkoutCandidate] {
        guard let data = defaults.data(forKey: key),
              let decoded = try? JSONDecoder().decode([AtriaDismissedWorkoutCandidate].self, from: data) else {
            return []
        }
        return decoded.filter { $0.end > $0.start }
    }

    static func save(_ candidates: [AtriaDismissedWorkoutCandidate],
                     defaults: UserDefaults = .standard) {
        let bounded = Array(candidates
            .filter { $0.end > $0.start }
            .sorted { $0.end > $1.end }
            .prefix(maximumCount))
        guard let data = try? JSONEncoder().encode(bounded) else { return }
        defaults.set(data, forKey: key)
    }
}

enum AtriaSleepStageIntegrity {
    /// Stage epochs may straddle a supported boundary by a few minutes, but
    /// they must never turn unsupported long capture gaps into inferred sleep.
    static func validates(_ segments: [SleepStageSegment], for sleep: UserConfirmedSleep) -> Bool {
        validates(segments,
                  start: sleep.start,
                  end: sleep.end,
                  duration: sleep.duration,
                  span: sleep.span)
    }

    static func validates(_ segments: [SleepStageSegment],
                          start: Date,
                          end: Date,
                          duration: TimeInterval,
                          span: TimeInterval) -> Bool {
        guard !segments.isEmpty, end > start, duration > 0 else { return false }
        let tolerance = max(5 * 60, duration * 0.05)
        var covered: TimeInterval = 0
        var nonAwake: TimeInterval = 0
        var seenIDs = Set<String>()
        var previousEnd: Date?

        for segment in segments {
            guard !segment.id.isEmpty,
                  seenIDs.insert(segment.id).inserted,
                  segment.end > segment.start,
                  segment.start >= start.addingTimeInterval(-1),
                  segment.end <= end.addingTimeInterval(1),
                  previousEnd.map({ segment.start >= $0 }) ?? true else { return false }
            covered += segment.duration
            if segment.stage != .awake {
                nonAwake += segment.duration
            }
            previousEnd = segment.end
        }

        let observedSpan = max(duration, span, end.timeIntervalSince(start))
        guard covered >= max(60, duration * 0.85),
              covered <= observedSpan + tolerance,
              nonAwake <= duration + tolerance else { return false }
        return true
    }

    /// A structurally valid research timeline is not automatically complete
    /// enough to present as the stage breakdown for a credited sleep episode.
    /// The stage rows and hypnogram imply that their non-awake epochs explain
    /// the same effective-sleep duration shown by the hero and used by
    /// Recovery. Fail closed when those authorities materially disagree rather
    /// than rendering precise-looking partial stage totals.
    static func reconcilesForPresentation(_ segments: [SleepStageSegment],
                                          effectiveSleepDuration: TimeInterval) -> Bool {
        guard !segments.isEmpty, effectiveSleepDuration > 0 else { return false }
        let classifiedSleep = segments.reduce(0) {
            $0 + ($1.stage == .awake ? 0 : max(0, $1.duration))
        }
        let tolerance = max(5 * 60, effectiveSleepDuration * 0.05)
        return abs(classifiedSleep - effectiveSleepDuration) <= tolerance
    }
}

