struct TrainingLoadSummary: Equatable {
    let acuteLoad: Double
    let chronicLoad: Double
    let ratio: Double?
    let monotony: Double?
    let confidence: String
    let readiness: String
    let acwrSignal: String
    let monotonySignal: String
    let targetBand: ClosedRange<Double>?
    let detail: String

    static let learning = TrainingLoadSummary(acuteLoad: 0,
                                              chronicLoad: 0,
                                              ratio: nil,
                                              monotony: nil,
                                              confidence: "learning",
                                              readiness: "learning",
                                              acwrSignal: "learning",
                                              monotonySignal: "learning",
                                              targetBand: nil,
                                              detail: "Atria needs more local strain history for load ratio.")

    var ratioText: String {
        ratio.map { String(format: "%.1f", $0) } ?? "Learning"
    }

    var targetBandText: String {
        guard let targetBand else { return "Learning" }
        return String(format: "%.1f-%.1f", targetBand.lowerBound, targetBand.upperBound)
    }

    var monotonyText: String {
        monotony.map { String(format: "%.1f", $0) } ?? "Learning"
    }

    var readinessText: String {
        readiness.capitalized
    }

    var acwrSignalText: String {
        acwrSignal.capitalized
    }

    var monotonySignalText: String {
        monotonySignal.capitalized
    }

    var acwrDetailText: String {
        switch acwrSignal {
        case "learning":
            return "Needs 14 local strain days."
        case "bad":
            if let ratio, ratio < 0.60 {
                return "Recent load is far below base; rebuild gradually."
            }
            return "Acute load is spiking vs your 28-day base."
        case "watch":
            if let ratio, ratio < 0.80 {
                return "Recent load is below base; add load gradually."
            }
            return "Acute load is ahead of your 28-day base."
        case "good":
            return "Acute load is aligned with your 28-day base."
        default:
            return "Load ratio is learning from local history."
        }
    }

    var monotonyDetailText: String {
        switch monotonySignal {
        case "learning":
            return "Needs 3 recent strain days."
        case "bad":
            return "Recent days are too repetitive; vary hard and easy days."
        case "watch":
            return "Recent load is repetitive; add more day-to-day variation."
        case "good":
            return "Recent load has healthy variation."
        default:
            return "Monotony is learning from local strain history."
        }
    }

    var signalSummaryText: String {
        guard confidence != "learning" else { return "Learning" }
        return "ACWR \(ratioText) \(acwrSignal), monotony \(monotonyText) \(monotonySignal)"
    }
}

/// Today's heart-rate zone minutes, bucketed the same way as
/// `AtriaAnalytics.Strain.MaxHeartRateZoneSeconds` (rest / warmup / fatBurn
/// Z2 / aerobic Z3 / anaerobic Z4 / max Z5). Computed off the main thread by
/// `SessionStore.refreshTodayHRZoneMinutesCache`, mirroring the
/// `TrainingLoadSummary` cache cadence.
struct TodayHRZoneMinutes: Equatable {
    let restMinutes: Int
    let warmupMinutes: Int
    let fatBurnMinutes: Int
    let aerobicMinutes: Int
    let anaerobicMinutes: Int
    let maxMinutes: Int
    /// True when at least one sample was recorded today (even if it was all
    /// resting) — distinguishes "0m active" from "no wear today".
    let hasSamples: Bool

    static let empty = TodayHRZoneMinutes(restMinutes: 0,
                                          warmupMinutes: 0,
                                          fatBurnMinutes: 0,
                                          aerobicMinutes: 0,
                                          anaerobicMinutes: 0,
                                          maxMinutes: 0,
                                          hasSamples: false)

    /// Z2 + Z3 + Z4 + Z5 — the "active" minutes shown as the glance value.
    var activeMinutes: Int {
        fatBurnMinutes + aerobicMinutes + anaerobicMinutes + maxMinutes
    }

    var valueText: String {
        hasSamples ? "\(activeMinutes)m" : "--"
    }

    var detailText: String {
        guard hasSamples else { return "No wear today" }
        let parts: [String] = [
            fatBurnMinutes > 0 ? "Z2 \(fatBurnMinutes)" : nil,
            aerobicMinutes > 0 ? "Z3 \(aerobicMinutes)" : nil,
            anaerobicMinutes > 0 ? "Z4 \(anaerobicMinutes)" : nil,
            maxMinutes > 0 ? "Z5 \(maxMinutes)" : nil
        ].compactMap { $0 }
        guard !parts.isEmpty else { return "Resting" }
        return parts.joined(separator: " · ")
    }

    var accessibilityDetailText: String {
        guard hasSamples else { return "No heart rate zone data today." }
        var parts: [String] = []
        if restMinutes > 0 { parts.append("\(restMinutes) minutes at rest") }
        if warmupMinutes > 0 { parts.append("\(warmupMinutes) minutes warmup") }
        if fatBurnMinutes > 0 { parts.append("\(fatBurnMinutes) minutes in zone 2, fat burn") }
        if aerobicMinutes > 0 { parts.append("\(aerobicMinutes) minutes in zone 3, aerobic") }
        if anaerobicMinutes > 0 { parts.append("\(anaerobicMinutes) minutes in zone 4, anaerobic") }
        if maxMinutes > 0 { parts.append("\(maxMinutes) minutes in zone 5, max effort") }
        guard !parts.isEmpty else { return "No time in an elevated heart rate zone today." }
        return "Heart rate zones today: " + parts.joined(separator: ", ") + "."
    }
}

struct VO2MaxEstimateSummary: Equatable {
    let value: Double?
    let confidence: String
    let detail: String
    let narrative: String
    let trendText: String
    let trendDetail: String
    let trendDelta: Double?

    /// Presentation only -- no estimator input. Falls back to the deterministic
    /// no-value token so VO2 max stops being the last value line saying
    /// "Learning" while Recovery, Stress, Respiration and Sleep beside it all
    /// say "--". The reason still shows: the row's DETAIL carries "Learning",
    /// so the pair reads "-- / Learning" rather than "Learning / Learning",
    /// which was the same word twice for one state.
    var valueText: String {
        value.map { String(format: "%.1f", $0) } ?? AtriaCompactMetricPresentation.noValue
    }

    /// One-line evidence status for glance surfaces. This deliberately exposes
    /// the producer's real blocker instead of replacing every not-ready state
    /// with a generic "Learning" label.
    var compactStatusText: String {
        guard value == nil else { return "Estimate" }
        switch detail {
        case "Need RHR":
            return "Needs resting HR"
        case "Need HRmax":
            return "Needs measured HRmax"
        default:
            return detail
        }
    }
}

struct BioAgeFactor: Equatable, Identifiable, Codable {
    enum Direction: String, Equatable, Codable {
        case younger
        case older
        case neutral
    }

    let id: String
    let label: String
    let ageEquivalent: Int
    let deltaVsChronological: Int
    let direction: Direction
    let weight: Double
    let detail: String

    var deltaText: String {
        if deltaVsChronological == 0 { return "neutral" }
        return "\(abs(deltaVsChronological))y \(deltaVsChronological < 0 ? "younger" : "older")"
    }
}

struct BiologicalAgeSummary: Equatable, Codable {
    let biologicalAge: Int?
    let chronologicalAge: Int
    let ageDelta: Int?
    let agingPaceText: String
    let agingPaceDetail: String
    let factors: [BioAgeFactor]
    let blockers: [String]
    let footnote: String
    /// Days of heart history behind an early (14–27 day) estimate. `nil` once
    /// the 28-day baseline is confident. Optional + defaulted so cached
    /// summaries written before this field existed decode as confident and
    /// every existing construction stays valid.
    var earlyEstimateDayCount: Int? = nil

    static let footnoteText = AtriaFitnessAge.footnoteText

    static func building(chronologicalAge: Int, blockers: [String]) -> BiologicalAgeSummary {
        BiologicalAgeSummary(biologicalAge: nil,
                             chronologicalAge: chronologicalAge,
                             ageDelta: nil,
                             agingPaceText: "Calibrating",
                             agingPaceDetail: "Needs 28 days before showing a fitness-age estimate.",
                             factors: [],
                             blockers: blockers,
                             footnote: footnoteText)
    }

    static func refreshing(chronologicalAge: Int) -> BiologicalAgeSummary {
        BiologicalAgeSummary(biologicalAge: nil,
                             chronologicalAge: chronologicalAge,
                             ageDelta: nil,
                             agingPaceText: "Updating",
                             agingPaceDetail: "Refreshing the weekly fitness-age estimate.",
                             factors: [],
                             blockers: ["weekly_estimate_loading"],
                             footnote: footnoteText)
    }

    var isReady: Bool { biologicalAge != nil }
    var isRefreshing: Bool { blockers.contains("weekly_estimate_loading") }

    /// True while a full estimate exists but the 28-day baseline is not yet
    /// confident (14–27 days of heart history).
    var isEarlyEstimate: Bool { isReady && earlyEstimateDayCount != nil }

    /// Display-ready qualifier for the early phase, e.g.
    /// "Early estimate · day 14 of 28". `nil` once confident.
    var earlyEstimateQualifierText: String? {
        guard isReady, let earlyEstimateDayCount else { return nil }
        return "Early estimate · day \(earlyEstimateDayCount) of \(AtriaFitnessAge.confidentBaselineDays)"
    }

    var valueText: String {
        biologicalAge.map(String.init) ?? "--"
    }

    var detailText: String {
        if isRefreshing { return "Refreshing weekly estimate" }
        guard let ageDelta else { return "Building baseline" }
        if ageDelta == 0 { return "Matches your age" }
        return "\(abs(ageDelta))y \(ageDelta < 0 ? "younger" : "older")"
    }

    var narrative: String {
        if isRefreshing { return "Updating weekly estimate" }
        guard isReady else { return "Calibrating 28-day baseline" }
        return "Five-input fitness estimate"
    }

    var blockerText: String {
        blockers.isEmpty ? footnote : blockers.map(Self.humanBlocker).joined(separator: " · ")
    }

    /// A compact, deterministic reason for cards where the full blocker list
    /// would make the surface look broken. No estimate is shown until every
    /// existing evidence gate passes.
    var compactStatusText: String {
        if isRefreshing { return "Updating weekly estimate" }
        if isReady { return detailText }
        guard let first = blockers.first else { return "Building 28-day baseline" }
        switch first {
        case "vo2max_learning":
            return "VO₂ max is still learning"
        case "resting_hr_learning":
            return "Building resting HR baseline"
        case "hrv_learning":
            return "Building HRV baseline"
        case "sleep_history_thin":
            return "3 sleep nights required"
        case "training_load_learning":
            return "Building training-load history"
        default:
            return "Building \(Self.humanBlocker(first))"
        }
    }

    /// The producer keeps machine tokens (pinned, log-friendly); the UI never
    /// shows snake_case to a human.
    private static func humanBlocker(_ raw: String) -> String {
        switch raw {
        case "vo2max_learning": return "VO₂ max learning"
        case "resting_hr_learning": return "resting HR baseline"
        case "hrv_learning": return "HRV baseline"
        case "sleep_history_thin": return "3 sleep nights"
        case "training_load_learning": return "training-load history"
        default: return raw.replacingOccurrences(of: "_", with: " ")
        }
    }
}

