    private func recentCanonicalSessions(windowDays: Int? = nil,
                                         limitSessions: Int? = nil,
                                         includeActiveJournal: Bool = false,
                                         now: Date = Date()) -> [SavedSession] {
        var recent = canonicalSessions(includeActiveJournal: includeActiveJournal)
        if let windowDays {
            let cutoff = now.addingTimeInterval(-Double(windowDays) * 24 * 60 * 60)
            recent = recent.filter { $0.start >= cutoff }
        }
        if let limitSessions {
            recent = Array(recent.prefix(max(1, limitSessions)))
        }
        return recent
    }

    private func canonicalSessions(includeActiveJournal: Bool = false) -> [SavedSession] {
        guard includeActiveJournal, let active = activeJournalSessionIfFresh() else {
            return cachedCanonicalSessions
        }
        return Self.makeCanonicalSessions(from: cachedCanonicalSessions + [active],
                                          preferredSession: preferredSession)
    }

    private nonisolated static func makeCanonicalSessions(from source: [SavedSession],
                                                          preferredSession: ((SavedSession, SavedSession) -> Bool)? = nil) -> [SavedSession] {
        var byID: [UUID: SavedSession] = [:]
        for session in source {
            if let existing = byID[session.id] {
                let prefersIncoming = preferredSession?(session, existing)
                    ?? defaultPreferredSession(session, over: existing)
                byID[session.id] = prefersIncoming ? session : existing
            } else {
                byID[session.id] = session
            }
        }
        return byID.values.sorted { lhs, rhs in
            if lhs.start != rhs.start { return lhs.start > rhs.start }
            return lhs.end > rhs.end
        }
    }

    nonisolated static func canonicalSessionsAfterUpsert(
        _ session: SavedSession,
        into cached: [SavedSession],
        preferredSession: ((SavedSession, SavedSession) -> Bool)? = nil,
        replacesSameID: Bool = false
    ) -> [SavedSession] {
        var next = cached
        if let existingIndex = next.firstIndex(where: { $0.id == session.id }) {
            let existing = next[existingIndex]
            if !replacesSameID {
                let prefersIncoming = preferredSession?(session, existing)
                    ?? defaultPreferredSession(session, over: existing)
                guard prefersIncoming else { return next }
            }
            next.remove(at: existingIndex)
        }

        let destination = canonicalInsertionIndex(in: next, for: session)
        next.insert(session, at: destination)
        return next
    }

    private nonisolated static func canonicalInsertionIndex(
        in orderedSessions: [SavedSession],
        for session: SavedSession
    ) -> Int {
        var low = 0
        var high = orderedSessions.count
        while low < high {
            let mid = (low + high) / 2
            let existing = orderedSessions[mid]
            if existing.start > session.start
                || (existing.start == session.start && existing.end > session.end) {
                low = mid + 1
            } else {
                high = mid
            }
        }
        return low
    }

    private nonisolated static func defaultPreferredSession(_ lhs: SavedSession, over rhs: SavedSession) -> Bool {
        if lhs.points.count != rhs.points.count {
            return lhs.points.count > rhs.points.count
        }
        if lhs.rrSampleCount != rhs.rrSampleCount {
            return lhs.rrSampleCount > rhs.rrSampleCount
        }
        if lhs.end != rhs.end {
            return lhs.end > rhs.end
        }
        return lhs.start > rhs.start
    }

    private func activeJournalSessionIfFresh(now: Date = Date()) -> SavedSession? {
        Self.loadActiveJournalSessionIfFresh(now: now)
    }

    /// Sleep settlement is allowed to consume a recently-ended resident journal
    /// after live/current freshness has expired. A phone can suspend, Bluetooth
    /// can be toggled, or the wearer can remove the strap at wake; none of those
    /// events should make the already-durable overnight HR/RR disappear from the
    /// morning projection merely because its last sample is more than 90 seconds
    /// old. Keep this scope equal to the BLE journal's bounded 18-hour authority.
    /// Present-tense consumers continue using `loadActiveJournalSessionIfFresh`.
    nonisolated static let residentSleepEvaluationJournalMaximumAge: TimeInterval = 18 * 60 * 60

    nonisolated static func activeJournalRecordIsEligibleForSleepEvaluation(
        _ record: ActiveSessionJournalRecord,
        now: Date,
        maximumEvidenceAge: TimeInterval = residentSleepEvaluationJournalMaximumAge,
        futureTolerance: TimeInterval = 5 * 60
    ) -> Bool {
        guard record.schema == ActiveSessionJournal.schema,
              maximumEvidenceAge > 0,
              record.samples.count > 1,
              let latestEvidenceAt = record.samples.max(by: { $0.t < $1.t })?.t else {
            return false
        }
        let evidenceAge = now.timeIntervalSince(latestEvidenceAt)
        return evidenceAge >= -futureTolerance && evidenceAge <= maximumEvidenceAge
    }

    /// File-backed sleep-only projection of the bounded resident journal. This
    /// deliberately does not claim that the stream is currently live.
    private nonisolated static func loadResidentJournalSessionForSleepEvaluation(
        now: Date = Date()
    ) -> SavedSession? {
        guard let record = ActiveSessionJournal.load(),
              activeJournalRecordIsEligibleForSleepEvaluation(record, now: now) else {
            return nil
        }
        return makeActiveJournalSession(from: record)
    }

    /// File-backed live-session projection. Callers on latency-sensitive paths
    /// must invoke this from a background executor: even when journal decoding
    /// hits its cache, ordering and mapping the growing sample arrays is O(n).
    private nonisolated static func loadActiveJournalSessionIfFresh(now: Date = Date()) -> SavedSession? {
        guard let record = ActiveSessionJournal.load(),
              record.schema == ActiveSessionJournal.schema,
              now.timeIntervalSince(record.updatedAt) <= 90 else {
            return nil
        }
        return makeActiveJournalSession(from: record)
    }

    private nonisolated static func makeActiveJournalSession(
        from record: ActiveSessionJournalRecord
    ) -> SavedSession? {
        let samples = record.samples.sorted { $0.t < $1.t }
        guard let first = samples.first, let last = samples.last, samples.count > 1 else {
            return nil
        }
        let rr = (record.rrSamples ?? [])
            .filter { $0.t >= first.t && $0.t <= last.t.addingTimeInterval(1) }
            .sorted { $0.t < $1.t }
        let researchAggregates = AtriaBLEManager.validatedResearchAggregates(from: record)
        let label = record.label.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            ? "All-day wear active"
            : "\(record.label) active"
        return SavedSession(id: record.id,
                            start: first.t,
                            end: last.t,
                            label: label,
                            points: samples.map { SavedSession.Point(t: $0.t.timeIntervalSince(first.t), bpm: $0.bpm) },
                            hrv: nil,
                            rrPoints: rr.isEmpty ? nil : rr.map {
                                SavedSession.RRPoint(t: $0.t.timeIntervalSince(first.t),
                                                     ms: $0.ms,
                                                     source: $0.source)
                            },
                            hrvReferenceValidated: false,
                            motionHintCount: nil,
                            motionHintKinds: nil,
                            motionEvidenceSource: "active_journal_unvalidated",
                            motionEvidenceValidated: false,
                            motionShortCount: nil,
                            motionShortMean: nil,
                            motionShortMin: nil,
                            motionShortMax: nil,
                            motionShortOverOneCount: nil,
                            sensorResearchProbeFrames: researchAggregates?.sensorProbeFrames,
                            spo2ResearchCandidateFrames: researchAggregates?.spo2CandidateFrames,
                            skinTempResearchCandidateFrames: researchAggregates?.skinTempCandidateFrames,
                            skinTempResearchCandidateValueSum: researchAggregates?.skinTempCandidateValueSum,
                            skinTempResearchCandidateValueCount: researchAggregates?.skinTempCandidateValueCount,
                            hrRaw2A37: record.rawHRNotifications,
                            hrAccepted: record.acceptedHRSamples,
                            hrZero: record.zeroHRSamples,
                            hrArtifactHeld: record.heldArtifacts,
                            hrArtifactDropped: record.droppedArtifacts,
                            hrRawGaps: record.rawHRGaps,
                            hrAcceptedGaps: record.acceptedHRGaps,
                            hrMaxRawGap: record.maxRawHRGap,
                            hrMaxAcceptedGap: record.maxAcceptedHRGap,
                            eventTimeZoneIdentifier: record.eventTimeZoneIdentifier ?? TimeZone.current.identifier)
    }

    private func preferredSession(_ candidate: SavedSession, over existing: SavedSession) -> Bool {
        Self.preferredSession(candidate, over: existing)
    }

    private nonisolated static func preferredSession(_ candidate: SavedSession, over existing: SavedSession) -> Bool {
        if candidate.points.count != existing.points.count {
            return candidate.points.count > existing.points.count
        }
        if candidate.duration != existing.duration {
            return candidate.duration > existing.duration
        }
        return candidate.end > existing.end
    }

    private nonisolated static func mergedSessions(primary: [SavedSession], secondary: [SavedSession]) -> [SavedSession] {
        var byID: [UUID: SavedSession] = [:]
        for session in secondary + primary {
            if let existing = byID[session.id], !preferredSession(session, over: existing) {
                continue
            }
            byID[session.id] = session
        }
        return byID.values.sorted { $0.start > $1.start }
    }

    /// Backup restore is a recovery operation, never a rollback that silently
    /// deletes sessions recorded after the backup. Seed from the backup, then
    /// let every current UUID win exactly as it exists now (including user
    /// edits that may intentionally contain fewer points or a shorter window).
    nonisolated static func sessionsAfterBackupRestore(current: [SavedSession],
                                                       backup: [SavedSession]) -> [SavedSession] {
        var byID: [UUID: SavedSession] = [:]
        for session in backup { byID[session.id] = session }
        for session in current {
            byID[session.id] = session
        }
        return byID.values.sorted { lhs, rhs in
            if lhs.start != rhs.start { return lhs.start > rhs.start }
            return lhs.end > rhs.end
        }
    }

    /// Workout restore follows the same non-destructive rule as session
    /// restore: records found only in the backup are recovered, while the
    /// current copy wins for a shared durable id so a newer local edit is never
    /// rolled back by an older backup.
    nonisolated static func confirmedWorkoutsAfterBackupRestore(
        current: [UserConfirmedWorkout],
        backup: [UserConfirmedWorkout]
    ) -> [UserConfirmedWorkout] {
        var byID: [String: UserConfirmedWorkout] = [:]
        for workout in backup { byID[workout.id] = workout }
        for workout in current {
            byID[workout.id] = workout
        }
        return byID.values.sorted { lhs, rhs in
            if lhs.start != rhs.start { return lhs.start > rhs.start }
            if lhs.end != rhs.end { return lhs.end > rhs.end }
            return lhs.id < rhs.id
        }
    }

    nonisolated static func confirmedSleepsAfterBackupRestore(
        current: [UserConfirmedSleep],
        backup: [UserConfirmedSleep]
    ) -> [UserConfirmedSleep] {
        var byID: [String: UserConfirmedSleep] = [:]
        for sleep in backup { byID[sleep.id] = sleep }
        for sleep in current { byID[sleep.id] = sleep }
        return byID.values.sorted { lhs, rhs in
            if lhs.start != rhs.start { return lhs.start > rhs.start }
            if lhs.end != rhs.end { return lhs.end > rhs.end }
            return lhs.id < rhs.id
        }
    }

    nonisolated static func dailyMetricsAfterBackupRestore(
        current: [SavedDailyMetric],
        backup: [SavedDailyMetric]
    ) -> [SavedDailyMetric] {
        var byDay: [Date: SavedDailyMetric] = [:]
        for metric in backup { byDay[metric.day] = metric }
        for metric in current { byDay[metric.day] = metric }
        return byDay.values.sorted { $0.day > $1.day }
    }

    nonisolated static func dailyRollupsAfterBackupRestore(
        current: [DailyRollupStoreEntry],
        backup: [DailyRollupStoreEntry]
    ) -> [DailyRollupStoreEntry] {
        var byDay: [Date: DailyRollupStoreEntry] = [:]
        for rollup in backup { byDay[rollup.day] = rollup }
        for rollup in current { byDay[rollup.day] = rollup }
        return byDay.values.sorted { $0.day > $1.day }
    }

    /// A restore should recover a profile into a fresh install, but it must not
    /// roll back an already-onboarded athlete's newer local edits.
    nonisolated static func profileAfterBackupRestore(
        current: AthleteProfile,
        backup: AthleteProfile
    ) -> AthleteProfile {
        if current.hasCompletedOnboarding || !backup.hasCompletedOnboarding {
            return current
        }
        return backup
    }

    @discardableResult
    private func reconcileSessionsBeforeLiveUpsert(reason: String) -> Bool {
        guard Self.shouldReconcileSessionsBeforeLiveUpsert(
            reason: reason,
            hasCompletedDeferredSessionLoad: hasCompletedDeferredSessionLoad
        ) else {
            return false
        }
        var merged = sessions
        if let data = try? Data(contentsOf: url),
           let diskSessions = try? JSONDecoder().decode([SavedSession].self, from: data),
           diskSessions.count > merged.count {
            merged = Self.mergedSessions(primary: merged, secondary: diskSessions)
        }
        if let backupURL = latestRestorableSessionBackupURL(),
           let envelope = try? Self.decodeSessionBackupEnvelope(at: backupURL),
           Self.supportedBackupSchemas.contains(envelope.schema),
           envelope.sessions.count > merged.count {
            merged = Self.mergedSessions(primary: merged, secondary: envelope.sessions)
        }
        guard merged.count > sessions.count else { return false }
        sessions = merged
        refreshSessionDerivedCaches()
        invalidateHomeDashboardDiagnosticsCache()
        AtriaDebugLog("ATRIADBG session_store_reconcile status=merged reason=%@ sessions=%d",
                      reason,
                      sessions.count)
        return true
    }

    nonisolated static func shouldReconcileSessionsBeforeLiveUpsert(
        reason: String,
        hasCompletedDeferredSessionLoad: Bool
    ) -> Bool {
        // The streaming deferred loader is the sole launch-time disk reader.
        // Live add/checkpoint paths operate on its resident canonical state and
        // must never decode sessions.json (or a potentially huge backup) again.
        // Explicit restore/reconcile callers may still request the legacy merge
        // after that launch transaction has completed.
        guard hasCompletedDeferredSessionLoad else { return false }
        return reason != "add" && reason != "checkpoint" && reason != "fast_launch"
    }

    func reconcileCanonicalSessionsFromBackupIfNeeded(reason: String) {
        guard reconcileSessionsBeforeLiveUpsert(reason: reason) else { return }
        markSessionPersistenceDirty()
        requestPersistenceFlush(reason: "session_reconcile_\(reason)")
    }

    @discardableResult
    func add(_ s: SavedSession, deferDerivedPublication: Bool = false) -> Bool {
        guard canonicalMutationAllowed else {
            AtriaDebugLog("ATRIADBG session_store_add status=blocked reason=restore_fence")
            return false
        }
        reconcileSessionsBeforeLiveUpsert(reason: "add")
        let replacedSession = sessions.first(where: { $0.id == s.id })
        let mode = upsertSession(s)
        markSessionPersistenceDirty(affectedSessions: [s] + (replacedSession.map { [$0] } ?? []))
        if let replacedSession {
            invalidateDailyDerivedDays(for: [replacedSession, s])
        }
        refreshSessionDerivedCachesAfterUpsert(
            s,
            replacesCanonicalSessionWithSameID: true,
            scheduleSleepReviewRefresh: !deferDerivedPublication
        )
        if !deferDerivedPublication {
            invalidateHomeDashboardDiagnosticsCache()
        }
        scheduleSessionFilePersist(reason: "add", delay: 0.10)
        if deferDerivedPublication {
            deferredSessionBoundaryDerivedPublicationGeneration &+= 1
            deferredSessionBoundaryDerivedPublicationPending = true
            // The automatic backup writer is already a coalescing utility
            // worker. Queue it now so the fast canonical flush is not the only
            // durable copy, but do not run any analytical projection on the
            // scene-update path.
            writeAutomaticSessionBackup(reason: "session-add-deferred-derived")
            AtriaDebugLog(
                "ATRIADBG session_store_add status=canonical_only reason=background_ble_boundary sessions=%d generation=%llu",
                sessions.count,
                deferredSessionBoundaryDerivedPublicationGeneration
            )
            return true
        }
        if mode == "replace" {
            rebuildBaselineFromEligibleSessions(reason: "session-add-replace")
        } else {
            learnBaselineIfEligible(from: s, reason: "session-add")
        }
        // A finalized session can change behavior correlations; recompute now that
        // the canonical cache + baseline are consistent (NOT in the checkpoint path).
        recomputeBehaviorInsights()
        refreshHistorySnapshotCache(deferred: true)
        refreshOverviewTrendPointsCache(deferred: true)
        refreshTrainingLoadSummaryCache(deferred: true)
        refreshTodayHRZoneMinutesCache(deferred: true)
        if let detection = s.detectedActivity(rest: baseline.restingInt ?? s.restingStable,
                                              maxHR: profile.maxHR) {
            AtriaDebugLog("ATRIADBG activity_detect kind=%@ confidence=%@ duration_s=%.0f avg_hr=%d peak_hr=%d reason=%@ motion_source=%@ motion_hints=%d motion_hint_kinds=%@ motion_validated=%d",
                  detection.kind.rawValue,
                  detection.confidence.rawValue,
                  detection.duration,
                  detection.avgHR,
                  detection.peakHR,
                  detection.reason,
                  s.motionEvidenceSourceValue,
                  s.motionHintCountValue,
                  s.motionHintKindsValue,
                  s.motionEvidenceValidatedValue ? 1 : 0)
        }
        writeAutomaticSessionBackup(reason: "session-add")
        return true
    }

    /// Resumes the analytical half of a background BLE boundary without ever
    /// replaying its O(n) baseline/RR work on MainActor. A newer boundary wins
    /// by generation; stale detached results cannot overwrite it.
    func resumeDeferredSessionBoundaryDerivedPublicationIfNeeded(reason: String) {
        guard deferredSessionBoundaryDerivedPublicationPending else { return }
        deferredSessionBoundaryDerivedPublicationPending = false
        let generation = deferredSessionBoundaryDerivedPublicationGeneration
        let sourceSessions = cachedCanonicalSessions
        let previousBaseline = baseline
        let profileSnapshot = profile
        let confirmedSleeps = cachedConfirmedSleeps

        Task.detached(priority: .utility) { [weak self,
                                            sourceSessions,
                                            previousBaseline,
                                            profileSnapshot,
                                            confirmedSleeps] in
            let rebuilt = Self.rebuildBaseline(
                from: sourceSessions,
                previousBaseline: previousBaseline,
                profile: profileSnapshot,
                confirmedSleeps: confirmedSleeps
            )
            await MainActor.run { [weak self] in
                guard let self,
                      generation == self.deferredSessionBoundaryDerivedPublicationGeneration else {
                    return
                }
                self.baseline = rebuilt
                Task.detached(priority: .utility) { rebuilt.save() }
                self.invalidateHomeDashboardDiagnosticsCache()
                self.invalidateSleepReviewCache(reason: "deferred_ble_boundary_\(reason)")
                self.refreshHistorySnapshotCache(deferred: true)
                self.refreshOverviewTrendPointsCache(deferred: true)
                self.refreshTrainingLoadSummaryCache(deferred: true)
                self.refreshTodayHRZoneMinutesCache(deferred: true)
                self.recomputeBehaviorInsights()
                self.publishDashboardRevision()
                AtriaDebugLog(
                    "ATRIADBG session_store_add status=derived_resumed reason=%@ sessions=%d generation=%llu",
                    reason,
                    self.sessions.count,
                    generation
                )
            }
        }
    }

    private func learnBaselineIfEligible(from session: SavedSession, reason: String) {
        if baseline.hrvQualificationVersion < PersonalBaseline.currentHRVQualificationVersion {
            rebuildBaselineFromEligibleSessions(reason: "\(reason)-hrv-qualification-migration")
            return
        }
        let bootstrapFromConfirmedSleep = cachedConfirmedSleeps.contains { sleep in
            Self.confirmedSleepIsPhysiologicalMainSleep(sleep)
                && session.start < sleep.end
                && session.end > sleep.start
        }
        guard let referenceRest = baseline.restingInt
                ?? (bootstrapFromConfirmedSleep ? session.restingStable : nil) else {
            AtriaDebugLog("ATRIADBG resting_baseline_sample status=skipped reason=missing_external_rest_reference label=%@ trigger=%@",
                          session.label,
                          reason)
            return
        }
        let evidence = session.baselineLearningEvidence(rest: referenceRest,
                                                        maxHR: profile.maxHR)
        guard evidence.accepted else {
            AtriaDebugLog("ATRIADBG resting_baseline_sample status=skipped reason=%@ value=%d source=%@ label=%@ duration_s=%.0f avg_hr=%d peak_hr=%d hrv_validated=%d trigger=%@",
                  evidence.reason,
                  evidence.value,
                  evidence.source,
                  session.label,
                  session.duration,
                  session.avg,
                  session.peak,
                  session.referenceValidatedHRV == nil ? 0 : 1,
                  reason)
            return
        }
        let sleepHRV = Self.confirmedMainSleepHRVEvidence(for: session,
                                                          confirmedSleeps: cachedConfirmedSleeps)
        baseline.learn(fromResting: evidence.value,
                       hrv: sleepHRV?.value ?? 0,
                       at: sleepHRV?.sleepEnd ?? session.end,
                       overnight: sleepHRV != nil)
        if canonicalMutationAllowed { baseline.save() }
        refreshHomeDashboardDiagnosticsCache()
        refreshHistorySnapshotCache(deferred: true)
        refreshOverviewTrendPointsCache(deferred: true)
        refreshTrainingLoadSummaryCache(deferred: true)
        refreshTodayHRZoneMinutesCache(deferred: true)
        AtriaDebugLog("ATRIADBG resting_baseline_sample status=accepted reason=%@ value=%d source=%@ label=%@ duration_s=%.0f avg_hr=%d peak_hr=%d hrv_validated=%d trigger=%@",
              evidence.reason,
              evidence.value,
              evidence.source,
              session.label,
              session.duration,
              session.avg,
              session.peak,
              session.referenceValidatedHRV == nil ? 0 : 1,
              reason)
    }

    private func rebuildBaselineFromEligibleSessions(
        reason: String,
        refreshDiagnosticsCache: Bool = true,
        refreshDerivedCaches: Bool = true
    ) {
        let previousRest = baseline.restingInt
        let previousSamples = baseline.restingSampleCount
        var rebuilt = PersonalBaseline()
        var accepted = 0
        var skipped = 0
        for session in canonicalSessions().sorted(by: { $0.start < $1.start }) {
            let bootstrapFromConfirmedSleep = cachedConfirmedSleeps.contains { sleep in
                Self.confirmedSleepIsPhysiologicalMainSleep(sleep)
                    && session.start < sleep.end
                    && session.end > sleep.start
            }
            guard let rest = rebuilt.restingInt
                    ?? previousRest
                    ?? (bootstrapFromConfirmedSleep ? session.restingStable : nil) else {
                skipped += 1
                continue
            }
            let evidence = session.baselineLearningEvidence(rest: rest, maxHR: profile.maxHR)
            if evidence.accepted {
                let sleepHRV = Self.confirmedMainSleepHRVEvidence(for: session,
                                                                  confirmedSleeps: cachedConfirmedSleeps)
                rebuilt.learn(fromResting: evidence.value,
                              hrv: sleepHRV?.value ?? 0,
                              at: sleepHRV?.sleepEnd ?? session.end,
                              overnight: sleepHRV != nil)
                accepted += 1
            } else {
                skipped += 1
            }
        }
        let confirmedSleepSeeds = Self.seedBaselineFromConfirmedSleeps(
            &rebuilt,
            confirmedSleeps: cachedConfirmedSleeps
        )
        baseline = rebuilt
        if canonicalMutationAllowed { baseline.save() }
        if refreshDiagnosticsCache {
            refreshHomeDashboardDiagnosticsCache()
        } else {
            cachedHomeDashboardDiagnostics = nil
        }
        if refreshDerivedCaches {
            refreshHistorySnapshotCache(deferred: true)
            refreshOverviewTrendPointsCache(deferred: true)
            refreshTrainingLoadSummaryCache(deferred: true)
            refreshTodayHRZoneMinutesCache(deferred: true)
        }
        AtriaDebugLog("ATRIADBG baseline_rebuild status=ok reason=%@ accepted=%d confirmed_sleep_seeds=%d skipped=%d old_rest=%@ new_rest=%@ old_samples=%d new_samples=%d hrv_baseline_samples=%d",
              reason,
              accepted,
              confirmedSleepSeeds,
              skipped,
              previousRest.map(String.init) ?? "learning",
              baseline.restingInt.map(String.init) ?? "learning",
              previousSamples,
              baseline.restingSampleCount,
              baseline.hrvSampleCount)
    }

    @discardableResult
    func checkpoint(_ s: SavedSession) -> Bool {
        guard canonicalMutationAllowed else {
            AtriaDebugLog("ATRIADBG session_store_checkpoint status=blocked reason=restore_fence")
            return false
        }
        let now = Date()
        reconcileSessionsBeforeLiveUpsert(reason: "checkpoint")
        _ = upsertSession(s, isLiveCheckpoint: true)
        markSessionPersistenceDirty(affectedSessions: [s])
        let refreshHRV = Self.shouldRefreshHRVOnLiveCheckpoint(
            lastRefreshAt: lastLiveHRVCheckpointRefreshAt,
            now: now,
            rrSampleCount: s.rrSampleCount,
            duration: s.duration
        )
        if refreshHRV {
            lastLiveHRVCheckpointRefreshAt = now
            Self.persistLiveHRVCheckpointRefreshDate(now)
        }
        refreshSessionDerivedCachesAfterUpsert(
            s,
            advancesBiologicalAgeSourceGeneration: false,
            refreshHRV: refreshHRV,
            scheduleSleepReviewRefresh: false
        )
        // ActiveSessionJournal is the crash-safe live authority. Keep this
        // checkpoint dirty and let finalization/backgrounding perform one
        // coalesced sessions.json write.
        if Self.shouldRefreshTodayHRZoneMinutesOnCheckpoint(
            lastRefreshAt: lastTodayHRZoneMinutesCheckpointRefreshAt,
            now: now
        ) {
            lastTodayHRZoneMinutesCheckpointRefreshAt = now
            refreshTodayHRZoneMinutesCache(deferred: true)
        }
        runResidentMorningSettlementIfUseful(now: now)
        if let detection = Self.checkpointDiagnosticValue(loggingEnabled: AtriaDebugLogging.isEnabled, makeValue: {
            s.detectedActivity(rest: baseline.restingInt ?? s.restingStable,
                               maxHR: profile.maxHR)
        }) {
            AtriaDebugLog("ATRIADBG activity_detect kind=%@ confidence=%@ duration_s=%.0f avg_hr=%d peak_hr=%d reason=%@ source=checkpoint motion_source=%@ motion_hints=%d motion_hint_kinds=%@ motion_validated=%d",
                  detection.kind.rawValue,
                  detection.confidence.rawValue,
                  detection.duration,
                  detection.avgHR,
                  detection.peakHR,
                  detection.reason,
                  s.motionEvidenceSourceValue,
                  s.motionHintCountValue,
                  s.motionHintKindsValue,
                  s.motionEvidenceValidatedValue ? 1 : 0)
        }
        return true
    }

    /// Three qualified five-minute windows are the minimum honest RMSSD input.
    /// Do not consume the four-hour cadence before a live session can possibly
    /// produce a ready value; once eligible, one scan per cadence is sufficient.
    /// Finalized sessions bypass this helper and always refresh exactly.
    nonisolated static func shouldRefreshHRVOnLiveCheckpoint(
        lastRefreshAt: Date?,
        now: Date,
        rrSampleCount: Int,
        duration: TimeInterval,
        interval: TimeInterval = liveHRVCheckpointRefreshInterval
    ) -> Bool {
        guard rrSampleCount >= 720, duration >= 15 * 60 else { return false }
        guard let lastRefreshAt else { return true }
        guard now >= lastRefreshAt else { return true }
        return now.timeIntervalSince(lastRefreshAt) >= interval
    }

    /// The expensive live-session HRV source scan has a process-independent
    /// cadence. Without persisting this marker, force-quitting/reopening Atria
    /// repeatedly defeats the four-hour limit even though session load already
    /// reconstructed the same latest HRV cache.
    nonisolated static func readLiveHRVCheckpointRefreshDate(
        userDefaults: UserDefaults = .standard
    ) -> Date? {
        guard let seconds = userDefaults.object(forKey: liveHRVCheckpointLastRefreshKey) as? Double,
              seconds.isFinite else { return nil }
        return Date(timeIntervalSince1970: seconds)
    }

    nonisolated static func persistLiveHRVCheckpointRefreshDate(
        _ date: Date?,
        userDefaults: UserDefaults = .standard
    ) {
        guard let date else {
            userDefaults.removeObject(forKey: liveHRVCheckpointLastRefreshKey)
            return
        }
        userDefaults.set(date.timeIntervalSince1970,
                         forKey: liveHRVCheckpointLastRefreshKey)
    }

    nonisolated static func checkpointDiagnosticValue<Value>(
        loggingEnabled: Bool,
        makeValue: () -> Value?
    ) -> Value? {
        guard loggingEnabled else { return nil }
        return makeValue()
    }

    nonisolated static func shouldRefreshTodayHRZoneMinutesOnCheckpoint(
        lastRefreshAt: Date?,
        now: Date,
        minimumInterval: TimeInterval = 60
    ) -> Bool {
        guard let lastRefreshAt else { return true }
        return now.timeIntervalSince(lastRefreshAt) >= minimumInterval
    }

    private var lastResidentMorningSettlementCheckpointAt: Date?

    private func runResidentMorningSettlementIfUseful(now: Date) {
        guard hasCompletedDeferredSessionLoad else { return }
        let learnedWindowEnd = Self.learnedDutyCycleSleepWindow(defaults: .standard)?.end
        guard Self.shouldAttemptResidentMorningSettlement(now: now,
                                                          learnedWindowEndMinute: learnedWindowEnd,
                                                          lastAttemptAt: lastResidentMorningSettlementCheckpointAt) else {
            return
        }
        lastResidentMorningSettlementCheckpointAt = now
        autoConfirmSleepOnForegroundIfUseful(reason: "resident_morning_checkpoint")
    }

    nonisolated static func shouldAttemptResidentMorningSettlement(
        now: Date,
        learnedWindowEndMinute: Int?,
        lastAttemptAt: Date?,
        calendar: Calendar = .current,
        minimumInterval: TimeInterval = 30 * 60
    ) -> Bool {
        if let lastAttemptAt, now.timeIntervalSince(lastAttemptAt) < minimumInterval {
            return false
        }
        let nowMinute = minutesOfDay(now, calendar: calendar)
        if let learnedWindowEndMinute {
            let end = min(max(learnedWindowEndMinute, 0), 1_439)
            let minutesAfterWakeBoundary = (nowMinute - end + 1_440) % 1_440
            return minutesAfterWakeBoundary <= 5 * 60
        }
        return nowMinute >= WakeBoundaryDefaults.fallbackMorningCoreStartMin
            && nowMinute <= WakeBoundaryDefaults.fallbackMorningCoreEndMin
    }

    func delete(_ offsets: IndexSet) {
        guard canonicalMutationAllowed else { return }
        let removedSessions = offsets.compactMap { sessions.indices.contains($0) ? sessions[$0] : nil }
        sessions.remove(atOffsets: offsets)
        markSessionPersistenceDirty(affectedSessions: removedSessions)
        invalidateDailyDerivedDays(for: removedSessions)
        refreshSessionDerivedCaches()
        invalidateHomeDashboardDiagnosticsCache()
        rebuildBaselineFromEligibleSessions(reason: "session-delete")
        recomputeBehaviorInsights()
        scheduleSessionFilePersist(reason: "delete", delay: 0.10)
        writeAutomaticSessionBackup(reason: "session-delete")
    }

    private func invalidateDailyDerivedDays(for sessions: [SavedSession],
                                            calendar: Calendar = .current) {
        for session in sessions {
            pendingDailyDerivedInvalidationDays.insert(
                EventCivilTime.day(containing: session.start,
                                   eventTimeZoneIdentifier: session.eventTimeZoneIdentifier,
                                   outputCalendar: calendar)
            )
            pendingDailyDerivedInvalidationDays.insert(Self.morningMetricDay(for: session, calendar: calendar))
        }
    }

    func deleteSession(id: UUID) {
        guard let index = sessions.firstIndex(where: { $0.id == id }) else { return }
        delete(IndexSet(integer: index))
    }

    func updateProfile(_ edit: (inout AthleteProfile) -> Void) {
        guard canonicalMutationAllowed else { return }
        var next = profile
        edit(&next)
        next.clamp()
        guard next != profile else { return }
        profile = next
        profile.save()
        invalidateHomeDashboardDiagnosticsCache()
        refreshHistorySnapshotCache(deferred: true)
        refreshOverviewTrendPointsCache(deferred: true)
        refreshTrainingLoadSummaryCache(deferred: true)
        refreshTodayHRZoneMinutesCache(deferred: true)
        AtriaDebugLog("ATRIADBG strain_profile age=%d source=%@ max_hr=%d measured_max_hr=%d",
              profile.age, profile.maxHRSource.rawValue, profile.maxHR, profile.measuredMaxHR)
        writeAutomaticSessionBackup(reason: "profile-update")
    }

    private func refreshMaxHRSuggestion(reason: String,
                                        now: Date = Date(),
                                        calendar: Calendar = .current,
                                        force: Bool = false) {
        if !force {
            let monthKey = Self.monthKey(for: now, calendar: calendar)
            let prior = UserDefaults.standard.string(forKey: Self.maxHRSuggestionLastRollupMonthKey)
            guard prior != monthKey || cachedMaxHRSuggestion == nil else { return }
            UserDefaults.standard.set(monthKey, forKey: Self.maxHRSuggestionLastRollupMonthKey)
        }
        cachedMaxHRSuggestion = makeMaxHRSuggestion(now: now, calendar: calendar)
        AtriaDebugLog("ATRIADBG max_hr_suggestion_rollup status=%@ reason=%@ observed_peak=%d current_max_hr=%d",
                      cachedMaxHRSuggestion == nil ? "none" : "ready",
                      reason,
                      cachedMaxHRSuggestion?.observedPeak ?? 0,
                      profile.maxHR)
    }

    private static func monthKey(for date: Date, calendar: Calendar) -> String {
        let components = calendar.dateComponents([.year, .month], from: date)
        return String(format: "%04d-%02d", components.year ?? 0, components.month ?? 0)
    }

    private func makeMaxHRSuggestion(now: Date = Date(), calendar: Calendar = .current) -> AtriaMaxHRSuggestion? {
        let windowStart = calendar.date(byAdding: .day,
                                        value: -AtriaMaxHRSuggestionEngine.lookbackDays,
                                        to: calendar.startOfDay(for: now))
            ?? now.addingTimeInterval(TimeInterval(-AtriaMaxHRSuggestionEngine.lookbackDays * 24 * 60 * 60))
        let peaks = canonicalSessions()
            .filter { $0.start >= windowStart && $0.start <= now }
            .map(\.peak)
        return AtriaMaxHRSuggestionEngine.suggestion(sessionPeaks: peaks,
                                                     currentMaxHR: profile.maxHR,
                                                     dismissed: AtriaMaxHRSuggestionEngine.loadDismissal(),
                                                     now: now,
                                                     calendar: calendar)
    }

    func maxHRSuggestion(now: Date = Date(), calendar: Calendar = .current) -> AtriaMaxHRSuggestion? {
        if cachedMaxHRSuggestion == nil {
            refreshMaxHRSuggestion(reason: "read", now: now, calendar: calendar, force: true)
        }
        return cachedMaxHRSuggestion
    }

    func dismissMaxHRSuggestion(observedPeak: Int, now: Date = Date()) {
        AtriaMaxHRSuggestionEngine.saveDismissal(observedPeak: observedPeak, now: now)
        refreshMaxHRSuggestion(reason: "dismiss", now: now, force: true)
    }

    func completeOnboarding(with profile: AthleteProfile) {
        guard canonicalMutationAllowed else { return }
        var next = profile
        next.completeOnboarding()
        guard next != self.profile else { return }
        self.profile = next
        self.profile.save()
        invalidateHomeDashboardDiagnosticsCache()
        refreshHistorySnapshotCache(deferred: true)
        refreshOverviewTrendPointsCache(deferred: true)
        refreshTrainingLoadSummaryCache(deferred: true)
        refreshTodayHRZoneMinutesCache(deferred: true)
        AtriaDebugLog("ATRIADBG onboarding complete=1 age=%d source=%@ max_hr=%d measured_max_hr=%d",
              self.profile.age,
              self.profile.maxHRSource.rawValue,
              self.profile.maxHR,
              self.profile.measuredMaxHR)
        writeAutomaticSessionBackup(reason: "onboarding")
    }

    func completeOnboardingFromLaunchIfRequested(arguments: [String] = ProcessInfo.processInfo.arguments) {
        guard AtriaDeveloperMode.isEnabled else { return }
        guard arguments.contains("--atria-complete-onboarding") else { return }
        completeOnboarding(with: profile)
    }

    func logBaselineMaturityFromLaunchIfRequested(arguments: [String] = ProcessInfo.processInfo.arguments) {
        guard arguments.contains("--atria-log-baseline") else { return }
        let restingStats = baseline.restingStats
        let hrvStats = baseline.lnRMSSDStats
        let latestValidated = latestReferenceValidatedHRV ?? 0
        let hrvReady = baseline.hrvSampleCount >= PersonalBaseline.trustedMinimumSamples
        let recoveryPersonalReady = hrvReady && baseline.restingStats != nil
        let recoveryValidatedReady = recoveryPersonalReady && latestValidated > 0
        AtriaDebugLog("ATRIADBG baseline_maturity sessions=%d resting_samples=%d resting_mean=%@ resting_sd=%@ hrv_baseline_samples=%d hrv_required=%d hrv_ready=%d latest_validated_hrv=%d recovery_personal_ready=%d recovery_validated_ready=%d",
              baseline.sessions,
              baseline.restingSampleCount,
              restingStats.map { String(format: "%.1f", $0.mean) } ?? "learning",
              restingStats.map { String(format: "%.1f", $0.sd) } ?? "learning",
              baseline.hrvSampleCount,
              PersonalBaseline.trustedMinimumSamples,
              hrvReady ? 1 : 0,
              latestValidated,
              recoveryPersonalReady ? 1 : 0,
              recoveryValidatedReady ? 1 : 0)
        AtriaDebugLog("ATRIADBG baseline_hrv_stats count=%d lnrmssd_mean=%@ lnrmssd_sd=%@ state=%@",
              hrvStats?.count ?? 0,
              hrvStats.map { String(format: "%.3f", $0.mean) } ?? "learning",
              hrvStats.map { String(format: "%.3f", $0.sd) } ?? "learning",
              recoveryPersonalReady ? "personal_baseline" : "learning")
    }

    func logCollectionHealthFromLaunchIfRequested(arguments: [String] = ProcessInfo.processInfo.arguments) {
        guard arguments.contains("--atria-log-collection-health") else { return }
        if !arguments.contains("--atria-log-collection-health-delay-fired"),
           let delayIndex = arguments.firstIndex(of: "--atria-log-collection-health-after"),
           arguments.indices.contains(arguments.index(after: delayIndex)),
           let delay = Double(arguments[arguments.index(after: delayIndex)]),
           delay > 0 {
            AtriaDebugLog("ATRIADBG collection_health_schedule delay_s=%.1f", delay)
            Task { @MainActor in
                try? await Task.sleep(for: .seconds(delay))
                if Task.isCancelled { return }
                var delayedArguments = arguments
                delayedArguments.append("--atria-log-collection-health-delay-fired")
                self.logCollectionHealthFromLaunchIfRequested(arguments: delayedArguments)
            }
            return
        }
        let phase = arguments.contains("--atria-log-collection-health-delay-fired") ? "delayed" : "launch"
        let journal = ActiveSessionJournal.diagnostics()
        let linkEvidence = AtriaBLEManager.linkEvidence().replacingOccurrences(of: " ", with: "_")
        let sampleEvidence = AtriaBLEManager.sampleGapEvidence().replacingOccurrences(of: " ", with: "_")
        let watchdogEvidence = AtriaBLEManager.watchdogRecoveryEvidence().replacingOccurrences(of: " ", with: "_")
        let rrState: String
        if journal.rrContinuityReady {
            rrState = "gate_b_window_ready"
        } else if journal.recentRRContinuityClean {
            rrState = "recent_rr_clean"
        } else if journal.hasCurrentRR {
            rrState = "rr_present_learning"
        } else {
            rrState = "hr_only_or_missing"
        }
        let collectionReady = journal.present && journal.fresh && journal.samples > 0
        let blocker: String
        if collectionReady {
            blocker = "none"
        } else if !journal.present {
            blocker = "active_journal_missing"
        } else if !journal.fresh {
            blocker = "active_journal_stale"
        } else {
            blocker = "active_journal_empty"
        }
        AtriaDebugLog("ATRIADBG collection_health phase=%@ status=%@ blocker=%@ active_journal_present=%d active_journal_fresh=%d active_journal_samples=%d active_journal_rr_values=%d active_journal_duration_s=%d active_journal_rr_coverage_3s_percent=%d active_journal_recent_rr_values=%d active_journal_recent_rr_duration_s=%d active_journal_recent_rr_coverage_3s_percent=%d rr_state=%@ gate_b_current_rr_ready=%d metric_promotions=0 %@ %@ %@",
              phase,
              collectionReady ? "ready" : "learning",
              blocker,
              journal.present ? 1 : 0,
              journal.fresh ? 1 : 0,
              journal.samples,
              journal.rrValues,
              Int(journal.duration.rounded()),
              journal.rrCoverage3Percent,
              journal.recentRRValues,
              Int(journal.recentRRDuration.rounded()),
              journal.recentRRCoverage3Percent,
              rrState,
              journal.rrContinuityReady ? 1 : 0,
              linkEvidence,
              sampleEvidence,
              watchdogEvidence)
    }

    func logGateReadinessFromLaunchIfRequested(arguments: [String] = ProcessInfo.processInfo.arguments) {
        guard arguments.contains("--atria-log-gate-readiness") else { return }
        if !arguments.contains("--atria-log-gate-readiness-delay-fired") {
            let delay = arguments.contains("--atria-standard-hr-only") || arguments.contains("--atria-long-wear-mode") ? 8.0 : 1.0
            AtriaDebugLog("ATRIADBG gate_readiness_ui schedule delay_s=%.1f reason=launch_arg", delay)
            Task { @MainActor in
                try? await Task.sleep(for: .seconds(delay))
                var delayedArguments = arguments
                delayedArguments.append("--atria-log-gate-readiness-delay-fired")
                self.logGateReadinessFromLaunchIfRequested(arguments: delayedArguments)
            }
            return
        }

        let rest = baseline.restingInt ?? 60
        let maxHR = profile.maxHR
        let hrvValidated = sessions.compactMap(\.referenceValidatedHRV).filter { $0 > 0 }.count
        let health = HealthKitExporter.diagnostics(for: sessions,
                                                   rest: rest,
                                                   maxHR: maxHR,
                                                   confirmedWorkouts: confirmedWorkouts,
                                                   confirmedSleeps: confirmedSleeps)
        let widget = WidgetSnapshotPublisher.diagnostics
        let archive = HistoricalArchive.diagnostics()
        let healthHRVReady = hrvValidated > 0 && health.planned.hrvSamples > 0
        let healthWorkoutReady = health.planned.workouts > 0
        let gateGPlatformBlockers = [
            health.entitlementPresent ? nil : "healthkit_entitlement",
            health.healthDataAvailable ? nil : "healthkit_unavailable",
            health.planned.hrSamples > 0 ? nil : "healthkit_hr_missing",
            health.readback.dataAppears ? nil : "healthkit_hr_readback_missing",
            widget.widgetTargetPresent ? nil : "widget_target",
            widget.appGroupEnabled ? nil : "app_group",
            widget.complicationTargetPresent ? nil : "complication_target"
        ].compactMap { $0 }
        let gateGMetricBlockers = [
            health.readback.overfilledTotalAtriaHRSamples > 0 ? "healthkit_hr_overfilled:\(health.readback.overfilledTotalAtriaHRSamples)" : nil,
            health.readback.expectedTotalAtriaHRSamples <= 0 || health.readback.expectedTotalCovered ? nil : "healthkit_hr_backfill_pending:\(health.readback.missingTotalAtriaHRSamples)",
            healthHRVReady ? nil : (hrvValidated > 0 ? "healthkit_hrv_missing" : "healthkit_hrv_reference_pending"),
            healthWorkoutReady ? nil : "healthkit_workout_learning"
        ].compactMap { $0 }
        let gateGPlatformReady = gateGPlatformBlockers.isEmpty
        let gateGStatus = gateGPlatformReady
            ? (gateGMetricBlockers.isEmpty ? "ready" : "metric_gated")
            : "partial"
        let gateGBlocker = gateGStatus == "ready"
            ? "none"
            : (gateGPlatformReady
               ? "platform_ready_metric_blockers:\(gateGMetricBlockers.joined(separator: "+"))"
               : "platform_blockers:\(gateGPlatformBlockers.joined(separator: "+"))")

        let strainSummary = strainValidationStatus(rest: rest, maxHR: maxHR)
        let healthReference = health.referenceAudit
        let externalHRReferenceReady = healthReference.externalReferenceReady || externalHRReferenceValidated
        let gateDBlocker = strainSummary.ready
            ? "none"
            : (externalHRReferenceReady
               ? strainSummary.primaryBlocker
               : (healthReference.status == "ok" ? healthReference.validationReason : "healthkit_reference_\(healthReference.status)"))

        let gateETraining = gateETrainingSummary(rest: rest, maxHR: maxHR)
        let gateEStatus: String
        let gateEBlocker: String
        if gateETraining.autoReady {
            gateEStatus = "ready"
            gateEBlocker = "none"
        } else if gateETraining.hasConfirmedEvidence {
            gateEStatus = "user_confirmed"
            gateEBlocker = "auto_detection_required:\(gateETraining.nextProof)"
        } else {
            gateEStatus = "partial"
            gateEBlocker = gateETraining.primaryBlocker
        }

        let trend90 = trendSummaries(rest: rest, maxHR: maxHR).first { $0.days == 90 }
        let gateFReadinessStatus = gateFStatus(summary: trend90, hrvValidated: hrvValidated)
        let gateHProtocolReady = archive.exists
            && archive.parseOK
            && archive.rows > 0
            && archive.rawPayloadRows > 0
            && archive.undecodableRows == 0
        let gateHBlocker = gateHProtocolReady
            ? "none"
            : (archive.exists ? "historical_archive_incomplete" : "historical_download_missing")
        let rows: [(gate: String, status: String, blocker: String)] = [
            ("A", "runtime_required", "physical_device_runtime"),
            ("B", hrvValidated > 0 ? "reference_partial" : "reference_pending", "external_rr_reference"),
            ("C", latestReferenceValidatedHRV != nil && baseline.hrvSampleCount >= PersonalBaseline.trustedMinimumSamples ? "ready" : "learning", "validated_hrv_baseline_\(baseline.hrvSampleCount)_of_\(PersonalBaseline.trustedMinimumSamples)"),
            ("D", strainSummary.ready ? "ready" : "partial", gateDBlocker),
            ("E", gateEStatus, gateEBlocker),
            ("F", gateFReadinessStatus, "coverage_\(trend90?.coveragePercent ?? 0)pct_hrv_gated"),
            ("G", gateGStatus, gateGBlocker),
            ("H", gateHProtocolReady ? "ready" : "partial", gateHBlocker)
        ]
        let readyCount = rows.filter { $0.status == "ready" }.count
        let evidence = rows
            .map { "\($0.gate)=\($0.status)[\($0.blocker)]" }
            .joined(separator: ";")
            .replacingOccurrences(of: " ", with: "_")
        AtriaDebugLog("ATRIADBG gate_readiness_ui source=launch_arg gates=%d ready=%d evidence=%@",
              rows.count,
              readyCount,
              evidence)
    }

    func logGateStatusFromLaunchIfRequested(arguments: [String] = ProcessInfo.processInfo.arguments) {
        guard arguments.contains("--atria-log-gate-status") else { return }
        let explicitDelay: Double? = {
            guard let delayIndex = arguments.firstIndex(of: "--atria-log-gate-status-after"),
                  arguments.indices.contains(arguments.index(after: delayIndex)),
                  let delay = Double(arguments[arguments.index(after: delayIndex)]),
                  delay > 0 else { return nil }
            return delay
        }()
        let liveCollectionSettleDelay: Double? = {
            guard !arguments.contains("--atria-log-gate-status-delay-fired"),
                  explicitDelay == nil,
                  arguments.contains("--atria-standard-hr-only") || arguments.contains("--atria-long-wear-mode") else {
                return nil
            }
            return 18
        }()
        if !arguments.contains("--atria-log-gate-status-delay-fired"),
           let delay = explicitDelay ?? liveCollectionSettleDelay {
            let clampedDelay = min(max(delay, 0), 86_400)
            AtriaDebugLog("ATRIADBG gate_status schedule delay_s=%.1f reason=%@", clampedDelay, explicitDelay != nil ? "launch_arg" : "live_collection_settle")
            Task { @MainActor in
                try? await Task.sleep(for: .seconds(clampedDelay))
                var delayedArguments = arguments
                delayedArguments.append("--atria-log-gate-status-delay-fired")
                logGateStatusFromLaunchIfRequested(arguments: delayedArguments)
            }
            return
        }
        let includeDeepReplay = arguments.contains("--atria-log-gate-status-deep")
        let mode = includeDeepReplay ? "deep" : "fast"
        let rest = baseline.restingInt ?? 60
        let hrvValidated = sessions.compactMap(\.referenceValidatedHRV).filter { $0 > 0 }.count
        let hrvBaselineReady = baseline.hrvSampleCount >= PersonalBaseline.trustedMinimumSamples
        let recoveryHighReady = hrvBaselineReady && latestReferenceValidatedHRV != nil
        let rrSessions = sessions.filter { $0.rrSampleCount > 0 }.count
        let rrSamples = totalRRSamples(in: sessions)
        let hrAcceptedSamples = totalHRAccepted(in: sessions)
        let boundedLargeStore = sessions.count > 120 || hrAcceptedSamples > 20_000 || rrSamples > 20_000
        let workoutReplayLimit = boundedLargeStore ? 80 : nil
        let workoutReplayScope = boundedLargeStore ? "bounded_large_store" : "full"
        AtriaDebugLog("ATRIADBG gate_status_start mode=%@ deep_replay=%d sessions=%d rr_sessions=%d rr_samples=%d hr_accepted=%d hrv_validated_sessions=%d hrv_baseline_samples=%d workout_replay_scope=%@ workout_replay_limit=%d",
              mode,
              includeDeepReplay ? 1 : 0,
              sessions.count,
              rrSessions,
              rrSamples,
              hrAcceptedSamples,
              hrvValidated,
              baseline.hrvSampleCount,
              workoutReplayScope,
              workoutReplayLimit ?? 0)
        if boundedLargeStore && !includeDeepReplay {
            logBoundedLargeStoreGateStatus(mode: mode,
                                           rest: rest,
                                           hrvValidated: hrvValidated,
                                           hrvBaselineReady: hrvBaselineReady,
                                           recoveryHighReady: recoveryHighReady,
                                           rrSessions: rrSessions,
                                           rrSamples: rrSamples,
                                           hrAcceptedSamples: hrAcceptedSamples,
                                           workoutReplayLimit: workoutReplayLimit)
            return
        }
        let rollups = dailyRollups(rest: rest, maxHR: profile.maxHR)
        let sleepDays = rollups.filter { $0.sleepReady > 0 }.count
        let sleepCandidateDays = rollups.filter { $0.sleepCandidates > 0 }.count
        let workoutDays = rollups.filter { $0.workouts > 0 }.count
        let motionHintSessions = sessions.filter { $0.motionHintCountValue > 0 }.count
        let motionHintTotal = sessions.reduce(0) { $0 + $1.motionHintCountValue }
        let sleepMotionSource = motionHintTotal > 0 ? "diagnostic_observe_only" : "unavailable"
        let trendSummaries = trendSummaries(rest: rest, maxHR: profile.maxHR)
        let trend90 = trendSummaries.first { $0.days == 90 }
        let trend90Blockers = trendBlockers(summary: trend90, hrvValidated: hrvValidated)
        let trend90AnomalyFlags = trend90.map { trendAnomalyFlags($0.anomalies) } ?? "none"
        let latestBackup = latestSessionBackupURL()
        let backupAvailable = latestBackup != nil
        let backupLabel = latestBackup.map { backupRelativePath(for: $0) } ?? "none"
        let backupCurrent = latestBackup.map { latestBackupMatchesCurrentStore($0) } ?? false
        AtriaDebugLog("ATRIADBG gate_status_progress stage=local_rollups mode=%@ days=%d sleep_days=%d sleep_candidate_days=%d workout_days=%d trend90_coverage_percent=%d backup_available=%d backup_current=%d",
              mode,
              rollups.count,
              sleepDays,
              sleepCandidateDays,
              workoutDays,
              trend90?.coveragePercent ?? 0,
              backupAvailable ? 1 : 0,
              backupCurrent ? 1 : 0)
        AtriaDebugLog("ATRIADBG gate_status_progress stage=healthkit_diagnostics_start mode=%@", mode)
        let confirmedWorkoutRecords = confirmedWorkouts
        let confirmedSleepRecords = confirmedSleeps
        let confirmedWorkoutCount = confirmedWorkoutRecords.count
        let confirmedSleepCount = confirmedSleepRecords.count
        let healthKit = HealthKitExporter.diagnostics(for: sessions,
                                                      rest: rest,
                                                      maxHR: profile.maxHR,
                                                      confirmedWorkouts: confirmedWorkoutRecords,
                                                      confirmedSleeps: confirmedSleepRecords)
        AtriaDebugLog("ATRIADBG gate_status_progress stage=healthkit_diagnostics_done mode=%@ entitlement=%d available=%d planned_hr=%d planned_workouts=%d planned_hrv=%d planned_sleeps=%d reference_status=%@ reference_ready=%d readback_status=%@ readback_missing_total_atria_hr_samples=%d readback_overfill_total_atria_hr_samples=%d readback_reconciliation=%@",
              mode,
              healthKit.entitlementPresent ? 1 : 0,
              healthKit.healthDataAvailable ? 1 : 0,
              healthKit.planned.hrSamples,
              healthKit.planned.workouts,
              healthKit.planned.hrvSamples,
              healthKit.planned.sleeps,
              healthKit.referenceAudit.status,
              healthKit.referenceAudit.externalReferenceReady ? 1 : 0,
              healthKit.readback.status,
              healthKit.readback.missingTotalAtriaHRSamples,
              healthKit.readback.overfilledTotalAtriaHRSamples,
              healthKit.readback.reconciliationStatus)
        let csvHRReference = csvHRReferenceDiagnostics
        let csvHRReferenceReady = externalHRReferenceValidated
        let externalHRReferenceReady = healthKit.referenceAudit.externalReferenceReady || csvHRReferenceReady
        let externalHRReferenceSourceLabel = healthKit.referenceAudit.externalReferenceReady
            ? "healthkit_validated"
            : self.externalHRReferenceSource
        let widget = WidgetSnapshotPublisher.diagnostics
        let checkpointArmed = UserDefaults.standard.bool(forKey: AtriaBLEManager.CheckpointDefaults.armed)
        let checkpointInterval = UserDefaults.standard.double(forKey: AtriaBLEManager.CheckpointDefaults.interval)
        let checkpointLabel = UserDefaults.standard.string(forKey: AtriaBLEManager.CheckpointDefaults.label) ?? "none"
        let checkpointSource = UserDefaults.standard.string(forKey: AtriaBLEManager.CheckpointDefaults.source) ?? "none"
        let checkpointLastStatus = UserDefaults.standard.string(forKey: AtriaBLEManager.CheckpointDefaults.lastStatus) ?? "none"
        let checkpointLastIndex = UserDefaults.standard.integer(forKey: AtriaBLEManager.CheckpointDefaults.lastIndex)
        let checkpointLastSamples = UserDefaults.standard.integer(forKey: AtriaBLEManager.CheckpointDefaults.lastSamples)
        let checkpointLastDuration = UserDefaults.standard.integer(forKey: AtriaBLEManager.CheckpointDefaults.lastDuration)
        let checkpointEvidence = "checkpoint_armed=\(checkpointArmed ? 1 : 0); checkpoint_interval_s=\(Int(checkpointInterval)); checkpoint_source=\(checkpointSource); checkpoint_label=\(checkpointLabel); checkpoint_last_status=\(checkpointLastStatus); checkpoint_last_index=\(checkpointLastIndex); checkpoint_last_samples=\(checkpointLastSamples); checkpoint_last_duration_s=\(checkpointLastDuration)"
        let linkEvidence = AtriaBLEManager.linkEvidence()
        let sampleEvidence = AtriaBLEManager.sampleGapEvidence()
        let watchdogEvidence = AtriaBLEManager.watchdogRecoveryEvidence()
        let batteryEvidence = AtriaBLEManager.batteryEvidence()
        let radioEvidence = AtriaBLEManager.radioEvidence()
        let offlineSyncEvidence = AtriaBLEManager.offlineSyncEvidence()
        let protocolEvidence = AtriaBLEManager.protocolEvidence()
        let journalEvidence = AtriaBLEManager.activeSessionJournalEvidence()
        let historicalArchive = HistoricalArchive.diagnostics()
        let historicalArchiveSchemas = historicalArchive.schemas.isEmpty ? "none" : historicalArchive.schemas.joined(separator: ",")
        let historicalArchiveLayouts = historicalArchive.layoutVersions.isEmpty ? "none" : historicalArchive.layoutVersions.joined(separator: ",")
        let historicalDownloadProtocolValidated = historicalArchive.exists
            && historicalArchive.parseOK
            && historicalArchive.rows > 0
            && historicalArchive.rawPayloadRows > 0
            && historicalArchive.undecodableRows == 0
        let historicalRRMetricReady = historicalDownloadProtocolValidated
            && historicalArchive.metricUsableRows > 0
            && historicalArchive.currentSessionUsableRows > 0
        let gateHStatus = historicalDownloadProtocolValidated ? "ready" : "partial"
        let reserveHR = max(profile.maxHR - rest, 0)
        let thresholdHR = rest + Int((Double(reserveHR) * 0.50).rounded())
        AtriaDebugLog("ATRIADBG gate_status_progress stage=workout_replay_start mode=%@ sessions=%d scope=%@ limit=%d",
              mode,
              sessions.count,
              workoutReplayScope,
              workoutReplayLimit ?? 0)
        let workoutReplay = replaySavedWorkoutReadiness(rest: rest,
                                                        maxHR: profile.maxHR,
                                                        limitSessions: workoutReplayLimit,
                                                        includeAggregates: workoutReplayLimit == nil,
                                                        includeActiveJournal: true)
        AtriaDebugLog("ATRIADBG gate_status_progress stage=workout_replay_done mode=%@ ready=%d best_source=%@ best_blocker=%@ best_next_action=%@ scope=%@ limit=%d",
              mode,
              workoutReplay.readySessions,
              workoutReplay.bestSource,
              workoutReplay.bestPrimaryBlocker,
              workoutReplay.bestNextAction,
              workoutReplayScope,
              workoutReplayLimit ?? 0)
        AtriaDebugLog("ATRIADBG gate_status_progress stage=historical_gap_repair_start mode=%@", mode)
        let historicalGapRepair = historicalGapRepairSummary(workoutReplay: workoutReplay,
                                                             archive: historicalArchive)
        AtriaDebugLog("ATRIADBG gate_status_progress stage=historical_gap_repair_done mode=%@ status=%@ reason=%@ metric_usable=%d",
              mode,
              historicalGapRepair.status,
              historicalGapRepair.reason,
              historicalGapRepair.metricUsable ? 1 : 0)
        AtriaDebugLog("ATRIADBG gate_status_progress stage=strain_validation_start mode=%@", mode)
        let strainValidation = strainValidationSummary(rest: rest, maxHR: profile.maxHR)
        AtriaDebugLog("ATRIADBG gate_status_progress stage=strain_validation_done mode=%@ ready=%d blocker=%@ stream_coverage_percent=%d max_hrr_percent=%d",
              mode,
              strainValidation.ready ? 1 : 0,
              strainValidation.primaryBlocker,
              strainValidation.streamCoveragePercent,
              Int((strainValidation.maxHRReserve * 100).rounded()))
        AtriaDebugLog("ATRIADBG gate_status_summary mode=%@ deep_replay=%d sessions=%d days=%d rest_hr=%d max_hr=%d hrv_validated_sessions=%d hrv_baseline_samples=%d backup_available=%d backup_current=%d healthkit_entitlement=%d healthkit_available=%d healthkit_hr_samples=%d healthkit_workouts=%d healthkit_hrv_samples=%d healthkit_sleeps=%d",
              mode,
              includeDeepReplay ? 1 : 0,
              sessions.count,
              rollups.count,
              rest,
              profile.maxHR,
              hrvValidated,
              baseline.hrvSampleCount,
              backupAvailable ? 1 : 0,
              backupCurrent ? 1 : 0,
              healthKit.entitlementPresent ? 1 : 0,
              healthKit.healthDataAvailable ? 1 : 0,
              healthKit.planned.hrSamples,
              healthKit.planned.workouts,
              healthKit.planned.hrvSamples,
              healthKit.planned.sleeps)
        let rrReplayLimit = includeDeepReplay ? 0 : 12
        AtriaDebugLog("ATRIADBG gate_status_progress stage=rr_replay_start mode=%@ rr_sessions=%d rr_samples=%d limit=%d",
              mode,
              rrSessions,
              rrSamples,
              rrReplayLimit)
        let rrReplay = replaySavedRRLedger(limitSessions: rrReplayLimit == 0 ? nil : rrReplayLimit,
                                           includeActiveJournal: true)
        AtriaDebugLog("ATRIADBG gate_status_progress stage=rr_replay_done mode=%@ ready=%d label=%@ raw=%d kept=%d conf=%d max_gap_s=%.1f reason=%@ limit=%d",
              mode,
              rrReplay.bestReady ? 1 : 0,
              rrReplay.bestSessionLabel,
              rrReplay.bestRaw,
              rrReplay.bestKept,
              rrReplay.bestConfidencePercent,
              rrReplay.bestMaxRRGapSeconds,
              rrReplay.reason,
              rrReplayLimit)
        let collectionEvidence = currentCollectionStatus().evidence
        let sleepEvidence = sleepEvidenceStatus(rest: rest, sleepDays: sleepDays)
        let sleepState = sleepEvidence.state
        let sleepEvidenceReady = sleepEvidence.ready
        let gateEReady = sleepEvidenceReady && workoutReplay.readySessions > 0
        let userConfirmedGateE = confirmedWorkoutCount > 0 && confirmedSleepCount > 0
        let gateEStatus = gateEReady
            ? "ready"
            : (userConfirmedGateE ? "user_confirmed" : "partial")
        logGateStatus("local", status: "dashboard",
