        }
    }

    func scheduleSleepValidationFromLaunchIfRequested(arguments: [String] = ProcessInfo.processInfo.arguments) {
        guard arguments.contains("--atria-verify-sleep") || arguments.contains("--atria-schedule-sleep-validation") else { return }
        let label = value(after: "--atria-verify-sleep-label", in: arguments)?
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let delay = doubleValue(after: "--atria-verify-sleep-after",
                                in: arguments,
                                default: 0,
                                range: 0...86_400)
        AtriaDebugLog("ATRIADBG sleep_validation schedule delay_s=%.1f label=%@", delay, label ?? "latest")
        Task { @MainActor in
            if delay > 0 {
                try? await Task.sleep(for: .seconds(delay))
            }
            await logSleepValidationWithReadinessRetry(label: label?.isEmpty == false ? label : nil)
        }
    }

    private func logSleepValidationWithReadinessRetry(label: String?) async {
        guard label == nil else {
            logSleepValidation(label: label)
            return
        }
        for (index, delay) in Self.sleepValidationRetryDelays.enumerated() {
            let readiness = sleepReadinessRetryState()
            guard readiness.shouldRetry else {
                logSleepValidation(label: nil)
                return
            }
            AtriaDebugLog("ATRIADBG sleep_validation status=deferred reason=%@ attempt=%d next_delay_s=%.0f state=%@ candidates=%d ready_candidates=%d pending_backfill=%d action=retry_existing_gates",
                          readiness.evidence.blocker,
                          index + 1,
                          delay,
                          readiness.evidence.state,
                          readiness.evidence.candidates,
                          readiness.evidence.readyCandidates,
                          readiness.pendingBackfill ? 1 : 0)
            try? await Task.sleep(for: .seconds(delay))
        }
        logSleepValidation(label: nil)
    }

    private func logSleepValidation(label: String?,
                                    preparedAggregateCandidates: [AggregateSleepCandidate]? = nil) {
        let rest = baseline.restingInt ?? 60
        let calendar = Calendar.current
        if label == nil, preparedAggregateCandidates == nil, Thread.isMainThread {
            let sourceSessions = canonicalSessions()
            let maxHR = profile.maxHR
            DispatchQueue.global(qos: .utility).async { [weak self] in
                let candidates = Self.aggregateSleepCandidates(in: sourceSessions,
                                                               rest: rest,
                                                               maxHR: maxHR,
                                                               calendar: calendar,
                                                               historicalMotionPolicy: .fullArchive)
                DispatchQueue.main.async {
                    self?.logSleepValidation(label: nil,
                                             preparedAggregateCandidates: candidates)
                }
            }
            return
        }
        let aggregateSleepCandidatesForValidation = label == nil
            ? (preparedAggregateCandidates ?? [])
            : []
        if label == nil, !aggregateSleepCandidatesForValidation.isEmpty {
            logSleepValidationCandidateMatrix(candidates: aggregateSleepCandidatesForValidation)
        }
        if label == nil,
           let aggregate = aggregateSleepCandidatesForValidation.first {
            let startHour = calendar.component(.hour, from: aggregate.start)
            let endHour = calendar.component(.hour, from: aggregate.end)
            let aggregateSource = sleepCandidateSource(for: aggregate)
            let matchedLabel = aggregate.kind == "nap_candidate"
                ? "nap_candidate_\(aggregate.sessions)_chunk\(aggregate.sessions == 1 ? "" : "s")"
                : (aggregate.sessions > 1
                   ? "aggregate_sleep_\(aggregate.sessions)_chunks"
                   : "aggregate_sleep_single_chunk")
            let validationReady = aggregate.motionEvidenceValidated && aggregate.confidence != .low
            let validationReason = validationReady
                ? "aggregate_overnight_low_hr_window"
                : sleepEvidenceBlocker(for: aggregate)
            AtriaDebugLog("ATRIADBG sleep_validation status=%@ reason=%@ label=%@ matched_label=%@ source=%@ duration_s=%.0f span_s=%.0f max_gap_s=%.0f samples=%d avg_hr=%d peak_hr=%d rest_hr=%d sleep_rhr=%d start_hour=%d end_hour=%d overnight=1 low_hr=1 sleep_candidates_matching=%d confidence=%@ fallback_available=1 fallback_source=%@ fallback_duration_s=%.0f fallback_span_s=%.0f fallback_chunks=%d fallback_diagnostic_only=1 motion_source=%@ motion_hints=%d motion_hint_kinds=%@ motion_validated=%d motion_short_count=%d motion_short_mean=%@ motion_short_min=%@ motion_short_max=%@ motion_short_over_1=%d motion_short_validated=0 historical_motion_status=%@ historical_motion_reason=%@ historical_motion_rows=%d historical_motion_validated_rows=%d historical_motion_coverage_s=%d historical_motion_archive_first_unix=%d historical_motion_archive_last_unix=%d historical_motion_nearest_separation_s=%d historical_motion_mean_delta=%@ historical_motion_p95_delta=%@ historical_motion_mag_stddev=%@ historical_motion_validated=%d detail=%@",
                  validationReady ? "ready" : "learning",
                  validationReason,
                  "latest",
                  matchedLabel,
                  aggregateSource,
                  aggregate.duration,
                  aggregate.span,
                  aggregate.maxGap,
                  aggregate.samples,
                  aggregate.avgHR,
                  aggregate.peakHR,
                  rest,
                  aggregate.restingHR,
                  startHour,
                  endHour,
                  aggregateSleepCandidatesForValidation.count,
                  aggregate.confidence.rawValue,
                  sleepFallbackSource(for: aggregate),
                  aggregate.duration,
                  aggregate.span,
                  aggregate.sessions,
                  aggregate.motionEvidenceSource,
                  aggregate.motionHintCount,
                  aggregate.motionHintKinds,
                  aggregate.motionEvidenceValidated ? 1 : 0,
                  aggregate.motionShortCount,
                  Self.formatDouble(aggregate.motionShortMean),
                  Self.formatDouble(aggregate.motionShortMin),
                  Self.formatDouble(aggregate.motionShortMax),
                  aggregate.motionShortOverOneCount,
                  aggregate.historicalMotionStatus,
                  aggregate.historicalMotionReason,
                  aggregate.historicalMotionRows,
                  aggregate.historicalMotionValidatedRows,
                  aggregate.historicalMotionCoverageSeconds,
                  aggregate.historicalMotionArchiveFirstUnix,
                  aggregate.historicalMotionArchiveLastUnix,
                  aggregate.historicalMotionNearestSeparationSeconds,
                  Self.formatDouble(aggregate.historicalMotionMeanVectorDelta),
                  Self.formatDouble(aggregate.historicalMotionP95VectorDelta),
                  Self.formatDouble(aggregate.historicalMotionMagnitudeStdDev),
                  aggregate.historicalMotionValidated ? 1 : 0,
                  aggregate.reason)
            return
        }
        let matching = sessions
            .filter { session in
                guard let label, !label.isEmpty else { return true }
                return session.label == label || session.label.hasPrefix("\(label) ")
            }
            .sorted {
                if abs($0.duration - $1.duration) > 60 {
                    return $0.duration > $1.duration
                }
                return $0.start > $1.start
            }
        guard let session = matching.first else {
            AtriaDebugLog("ATRIADBG sleep_validation status=learning reason=no_saved_session label=%@ sessions=%d rest_hr=%d max_hr=%d",
                  label ?? "latest", sessions.count, rest, profile.maxHR)
            return
        }
        let eventCalendar = EventCivilTime.eventCalendar(timeZoneIdentifier: session.eventTimeZoneIdentifier,
                                                         fallback: calendar)
        let startHour = eventCalendar.component(.hour, from: session.start)
        let endHour = eventCalendar.component(.hour, from: session.end)
        let overnight = startHour >= 20 || startHour <= 3 || endHour <= 10
        let lowHR = session.avg <= rest + 15 && session.peak <= rest + 35
        let durationOK = session.duration >= 3 * 60 * 60
        let detection = session.detectedActivity(rest: rest, maxHR: profile.maxHR, calendar: calendar)
        let isSleep = detection?.kind == .sleepCandidate
        let motionReady = session.motionEvidenceValidatedValue && detection?.confidence != .low
        let status = isSleep && motionReady ? "ready" : "learning"
        let reason: String
        if !durationOK {
            reason = "duration_below_3h"
        } else if !overnight {
            reason = "not_overnight"
        } else if !lowHR {
            reason = "hr_not_low"
        } else if !isSleep {
            reason = "detector_not_sleep"
        } else if !motionReady {
            reason = "sleep_low_confidence_motion_unvalidated"
        } else {
            reason = "overnight_low_hr_window"
        }
        AtriaDebugLog("ATRIADBG sleep_validation status=%@ reason=%@ label=%@ matched_label=%@ duration_s=%.0f samples=%d avg_hr=%d peak_hr=%d rest_hr=%d sleep_rhr=%d start_hour=%d end_hour=%d overnight=%d low_hr=%d sleep_candidates_matching=%d confidence=%@ motion_source=%@ motion_hints=%d motion_hint_kinds=%@ motion_validated=%d motion_short_count=%d motion_short_mean=%@ motion_short_min=%@ motion_short_max=%@ motion_short_over_1=%d motion_short_validated=0",
              status,
              reason,
              label ?? "latest",
              session.label,
              session.duration,
              session.points.count,
              session.avg,
              session.peak,
              rest,
              session.sleepCandidateRestingHR,
              startHour,
              endHour,
              overnight ? 1 : 0,
              lowHR ? 1 : 0,
              matching.filter {
                  $0.detectedActivity(rest: rest, maxHR: profile.maxHR, calendar: calendar)?.kind == .sleepCandidate
              }.count,
              detection?.confidence.rawValue ?? "none",
              session.motionEvidenceSourceValue,
              session.motionHintCountValue,
              session.motionHintKindsValue,
              session.motionEvidenceValidatedValue ? 1 : 0,
              session.motionShortCountValue,
              Self.formatDouble(session.motionShortMeanValue),
              Self.formatDouble(session.motionShortMinValue),
              Self.formatDouble(session.motionShortMaxValue),
              session.motionShortOverOneCountValue)
    }

    private func logSleepValidationCandidateMatrix(candidates: [AggregateSleepCandidate],
                                                   maxRows: Int = 6) {
        let preferred = Self.preferredSleepCandidateForReview(from: candidates)
        let readyCount = candidates.filter(Self.isAutoConfirmableMainSleepCandidate).count
        AtriaDebugLog("ATRIADBG sleep_candidate_matrix candidates=%d emitted=%d ready_candidates=%d preferred_kind=%@ preferred_start=%@ preferred_end=%@ policy=review_before_recovery",
                      candidates.count,
                      min(maxRows, candidates.count),
                      readyCount,
                      preferred?.kind ?? "none",
                      preferred.map { isoString($0.start) } ?? "none",
                      preferred.map { isoString($0.end) } ?? "none")

        for (index, candidate) in candidates.prefix(maxRows).enumerated() {
            let selected = preferred.map {
                $0.kind == candidate.kind
                    && abs($0.start.timeIntervalSince(candidate.start)) < 1
                    && abs($0.end.timeIntervalSince(candidate.end)) < 1
            } ?? false
            let autoConfirmable = Self.isAutoConfirmableMainSleepCandidate(candidate)
            AtriaDebugLog("ATRIADBG sleep_candidate rank=%d selected=%d kind=%@ source=%@ duration_s=%.0f span_s=%.0f max_gap_s=%.0f sessions=%d samples=%d avg_hr=%d peak_hr=%d sleep_rhr=%d confidence=%@ auto_confirmable=%d motion_source=%@ motion_validated=%d blocker=%@ fallback_source=%@ historical_motion_status=%@ historical_motion_reason=%@ historical_motion_rows=%d historical_motion_validated_rows=%d historical_motion_coverage_s=%d historical_motion_nearest_separation_s=%d detail=%@",
                          index + 1,
                          selected ? 1 : 0,
                          candidate.kind,
                          sleepCandidateSource(for: candidate),
                          candidate.duration,
                          candidate.span,
                          candidate.maxGap,
                          candidate.sessions,
                          candidate.samples,
                          candidate.avgHR,
                          candidate.peakHR,
                          candidate.restingHR,
                          candidate.confidence.rawValue,
                          autoConfirmable ? 1 : 0,
                          candidate.motionEvidenceSource,
                          candidate.motionEvidenceValidated ? 1 : 0,
                          sleepEvidenceBlocker(for: candidate),
                          sleepFallbackSource(for: candidate),
                          candidate.historicalMotionStatus,
                          candidate.historicalMotionReason,
                          candidate.historicalMotionRows,
                          candidate.historicalMotionValidatedRows,
                          candidate.historicalMotionCoverageSeconds,
                          candidate.historicalMotionNearestSeparationSeconds,
                          candidate.reason)
        }
    }

    func scheduleWorkoutValidationFromLaunchIfRequested(arguments: [String] = ProcessInfo.processInfo.arguments) {
        guard arguments.contains("--atria-schedule-workout-validation")
                || value(after: "--atria-verify-workout-label", in: arguments) != nil else { return }
        guard let label = value(after: "--atria-verify-workout-label", in: arguments),
              !label.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }
        let delay = doubleValue(after: "--atria-verify-workout-after",
                                in: arguments,
                                default: 0,
                                range: 0...86_400)
        AtriaDebugLog("ATRIADBG workout_validation schedule delay_s=%.1f label=%@", delay, label)
        Task { @MainActor in
            if delay > 0 {
                try? await Task.sleep(for: .seconds(delay))
            }
            logWorkoutValidation(label: label)
        }
    }

    private func logWorkoutValidation(label: String) {
        let rest = baseline.restingInt ?? 60
        let requestedLabel = label.trimmingCharacters(in: .whitespacesAndNewlines)
        let matching = sessions
            .filter { labelMatches($0.label, requested: requestedLabel) }
            .sorted { $0.duration > $1.duration }
        let aggregateMatching = aggregateWorkoutCandidates(rest: rest, maxHR: profile.maxHR, calendar: Calendar.current)
            .filter { aggregate in
                aggregate.labels.contains { labelMatches($0, requested: requestedLabel) }
                    || labelMatches(aggregate.label, requested: requestedLabel)
            }
        let singleCandidates = matching.map { session in
            (source: "single_session",
             chunks: 1,
             span: session.duration,
             label: session.label,
             duration: session.duration,
             samples: session.points.count,
             avgHR: session.avg,
             peakHR: session.peak,
             readiness: session.workoutReadiness(rest: rest, maxHR: profile.maxHR))
        }
        let aggregateCandidates = aggregateMatching.map { aggregate in
            (source: "aggregate_chunks",
             chunks: aggregate.sessions,
             span: aggregate.span,
             label: aggregate.label,
             duration: aggregate.duration,
             samples: aggregate.samples,
             avgHR: aggregate.avgHR,
             peakHR: aggregate.peakHR,
             readiness: aggregate.readiness)
        }
        let candidates = singleCandidates + aggregateCandidates
        guard let best = candidates.sorted(by: { lhs, rhs in
            if lhs.readiness.ready != rhs.readiness.ready { return lhs.readiness.ready }
            let lhsHasElevatedEvidence = lhs.readiness.elevatedSeconds > 0 || lhs.peakHR >= lhs.readiness.thresholdHR
            let rhsHasElevatedEvidence = rhs.readiness.elevatedSeconds > 0 || rhs.peakHR >= rhs.readiness.thresholdHR
            if lhsHasElevatedEvidence != rhsHasElevatedEvidence { return lhsHasElevatedEvidence }
            if lhs.readiness.longestElevatedBout != rhs.readiness.longestElevatedBout {
                return lhs.readiness.longestElevatedBout > rhs.readiness.longestElevatedBout
            }
            if lhs.readiness.elevatedSeconds != rhs.readiness.elevatedSeconds {
                return lhs.readiness.elevatedSeconds > rhs.readiness.elevatedSeconds
            }
            if lhs.peakHR != rhs.peakHR {
                return lhs.peakHR > rhs.peakHR
            }
            if lhs.readiness.observedDuration != rhs.readiness.observedDuration {
                return lhs.readiness.observedDuration > rhs.readiness.observedDuration
            }
            return lhs.readiness.maxSampleGap < rhs.readiness.maxSampleGap
        }).first else {
            AtriaDebugLog("ATRIADBG workout_validation status=learning reason=no_saved_session label=%@ sessions=%d rest_hr=%d max_hr=%d",
                  requestedLabel, sessions.count, rest, profile.maxHR)
            return
        }
        let readiness = best.readiness
        let status = readiness.ready ? "ready" : "learning"
        let reason = status == "ready" ? "sustained_elevated_hr" : readiness.reason
        let readyMatches = candidates.filter { $0.readiness.ready }.count
        AtriaDebugLog("ATRIADBG workout_validation status=%@ reason=%@ primary_blocker=%@ near_miss=%d near_miss_reason=%@ strength_candidate=%d strength_candidate_reason=%@ strength_diagnostic_only=1 next_action=%@ stream_coverage_percent=%d label=%@ matched_label=%@ source=%@ chunks=%d span_s=%.0f duration_s=%.0f observed_duration_s=%.0f dropped_gap_s=%.0f max_gap_s=%.1f gap_count=%d samples=%d avg_hr=%d peak_hr=%d p90_hr=%d p95_hr=%d p99_hr=%d rest_hr=%d max_hr=%d threshold_hr=%d threshold_gap_bpm=%d samples_above_threshold=%d samples_above_borderline=%d elevated_s=%.0f required_elevated_s=%.0f longest_bout_s=%.0f required_bout_s=%.0f borderline_threshold_hr=%d borderline_elevated_s=%.0f borderline_longest_bout_s=%.0f borderline_diagnostic_only=1 workouts_matching=%d aggregate_candidates=%d",
              status,
              reason,
              readiness.primaryBlocker,
              readiness.nearMiss ? 1 : 0,
              readiness.nearMissReason,
              readiness.strengthCandidate ? 1 : 0,
              readiness.strengthCandidateReason,
              readiness.nextAction,
              readiness.streamCoveragePercent,
              requestedLabel,
              best.label,
              best.source,
              best.chunks,
              best.span,
              best.duration,
              readiness.observedDuration,
              readiness.droppedGapSeconds,
              readiness.maxSampleGap,
              readiness.gapCount,
              best.samples,
              best.avgHR,
              best.peakHR,
              readiness.p90HR,
              readiness.p95HR,
              readiness.p99HR,
              rest,
              profile.maxHR,
              readiness.thresholdHR,
              readiness.thresholdGapBPM,
              readiness.samplesAboveThreshold,
              readiness.samplesAboveBorderline,
              readiness.elevatedSeconds,
              readiness.requiredElevatedSeconds,
              readiness.longestElevatedBout,
              readiness.requiredElevatedBout,
              readiness.borderlineThresholdHR,
              readiness.borderlineElevatedSeconds,
              readiness.borderlineLongestBout,
              readyMatches,
              aggregateMatching.count)
    }

    private func labelMatches(_ candidate: String, requested: String) -> Bool {
        candidate == requested || candidate.hasPrefix("\(requested) ")
    }

    @discardableResult
    func writeSessionBackup(label: String = "manual") -> URL? {
        guard Self.manualBackupRequestAllowed(
            restoreInitializationBlocked: restoreInitializationBlocked,
            restorePersistenceFenceActive: restorePersistenceFenceActive,
            userOperationInProgress: sessionBackupUserOperationInProgress
        ) else {
            AtriaDebugLog("ATRIADBG session_backup_manual status=busy reason=restore_or_operation_in_progress")
            return nil
        }
        return sessionBackupWorker.performSynchronously(
            makeSessionBackupWriteRequest(label: label)
        ).url
    }

    /// User-requested backup that preserves the existing archive format while
    /// keeping encoding, compression and filesystem work off MainActor.
    func writeSessionBackupAsync(label: String = "manual",
                                 completion: @escaping @MainActor (SessionBackupStatus) -> Void) {
        guard Self.manualBackupRequestAllowed(
            restoreInitializationBlocked: restoreInitializationBlocked,
            restorePersistenceFenceActive: restorePersistenceFenceActive,
            userOperationInProgress: sessionBackupUserOperationInProgress
        ) else {
            AtriaDebugLog("ATRIADBG session_backup_manual status=busy reason=restore_or_operation_in_progress")
            completion(SessionBackupStatus(available: cachedSessionBackupStatus.available,
                                           current: false,
                                           path: cachedSessionBackupStatus.path,
                                           sessions: cachedSessionBackupStatus.sessions,
                                           rrSamples: cachedSessionBackupStatus.rrSamples,
                                           bytes: cachedSessionBackupStatus.bytes,
                                           reason: "operation_in_progress"))
            return
        }
        sessionBackupStatusGeneration &+= 1
        let statusGeneration = sessionBackupStatusGeneration
        let request = makeSessionBackupWriteRequest(label: label)
        sessionBackupWorker.enqueueRequired(request) { [weak self] result in
            Task { @MainActor [weak self] in
                guard let self else { return }
                guard Self.backupStatusGenerationIsCurrent(
                    resultGeneration: statusGeneration,
                    currentGeneration: self.sessionBackupStatusGeneration
                ) else {
                    completion(self.cachedSessionBackupStatus)
                    return
                }
                let verified = await self.sessionBackupIOWorker.performAsync(
                    .verifyLatest(self.makeSessionBackupIOSnapshot())
                )
                guard Self.backupStatusGenerationIsCurrent(
                    resultGeneration: statusGeneration,
                    currentGeneration: self.sessionBackupStatusGeneration
                ) else {
                    completion(self.cachedSessionBackupStatus)
                    return
                }
                let status: SessionBackupStatus
                if case .verification(let next) = verified {
                    status = next
                } else {
                    status = result.status
                }
                self.cachedSessionBackupStatus = status
                self.cachedHomeDashboardDiagnostics = nil
                self.publishDashboardRevision()
                completion(status)
            }
        }
    }

    nonisolated static func manualBackupRequestAllowed(
        restoreInitializationBlocked: Bool,
        restorePersistenceFenceActive: Bool,
        userOperationInProgress: Bool
    ) -> Bool {
        !restoreInitializationBlocked
            && !restorePersistenceFenceActive
            && !userOperationInProgress
    }

    private func makeSessionBackupWriteRequest(label: String) -> SessionBackupWriteRequest {
        let rollups = dailyRollupHistory.isEmpty ? dailyRollupStore.rollups(last: 400) : dailyRollupHistory
        return SessionBackupWriteRequest(label: label,
                                         sessions: sessions,
                                         baseline: baseline,
                                         profile: profile,
                                         dailyMetrics: dailyMetricHistory,
                                         dailyRollups: rollups,
                                         confirmedSleeps: cachedConfirmedSleeps,
                                         confirmedWorkouts: cachedConfirmedWorkouts,
                                         backupDirectory: sessionBackupDirectory(),
                                         mirrorsToICloud: UserDefaults.standard.bool(forKey: Self.iCloudBackupEnabledKey))
    }

