                HistoryQuickStat(label: "Detected", value: "\(snapshot.detections.count)")
                HistoryQuickStat(label: "Baseline", value: "\(projectionStore.hrvBaselineSampleCount)/\(PersonalBaseline.trustedMinimumSamples)")
            }
